window.CODIGO_JAVA["inventario-operaciones-ms"] = {"src/main/java/com/mx/josesaid/develop/inventario/InventarioApplication.java": "package com.mx.josesaid.develop.inventario;\n\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\nimport org.springframework.boot.context.properties.ConfigurationPropertiesScan;\nimport org.springframework.scheduling.annotation.EnableScheduling;\n\n/** Punto de entrada de inventario-operaciones-ms. */\n@SpringBootApplication\n@EnableScheduling\n@ConfigurationPropertiesScan\npublic class InventarioApplication {\n\n    /** Arranca la aplicación Spring Boot. */\n    public static void main(String[] args) {\n        SpringApplication.run(InventarioApplication.class, args);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/api/InventarioControlador.java": "package com.mx.josesaid.develop.inventario.api;\n\nimport com.mx.josesaid.develop.inventario.application.InventarioService;\nimport com.mx.josesaid.develop.inventario.domain.Almacen;\nimport com.mx.josesaid.develop.inventario.domain.Articulo;\nimport com.mx.josesaid.develop.inventario.domain.EstatusOrden;\nimport com.mx.josesaid.develop.inventario.domain.Existencia;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoInventario;\nimport com.mx.josesaid.develop.inventario.domain.OrdenOperacion;\nimport com.mx.josesaid.develop.inventario.domain.TipoMovimiento;\nimport com.mx.josesaid.develop.inventario.domain.TipoOrden;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.Digits;\nimport jakarta.validation.constraints.DecimalMin;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.NotNull;\nimport jakarta.validation.constraints.Size;\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.ResponseStatus;\nimport org.springframework.web.bind.annotation.RestController;\nimport com.mx.josesaid.develop.inventario.infrastructure.idempotencia.Idempotencia;\nimport org.springframework.web.bind.annotation.RequestHeader;\nimport org.springframework.http.ResponseEntity;\n\n/**\n * Endpoints de inventario. Los de la especificación más dos altas necesarias para usar el servicio:\n * POST /articulos (OPERACIONES) y POST /almacenes (ALMACEN).\n */\n@RestController\n@RequestMapping(\"/v1\")\npublic class InventarioControlador {\n\n    private final InventarioService servicio;\n    private final Idempotencia idempotencia;\n\n    /** Recibe el servicio de inventario y el control de idempotencia. */\n    public InventarioControlador(InventarioService servicio, Idempotencia idempotencia) {\n        this.servicio = servicio;\n        this.idempotencia = idempotencia;\n    }\n\n    /** Da de alta un artículo con su SKU, unidad, mínimo y si requiere lote. */\n    @PostMapping(\"/articulos\")\n    @ResponseStatus(HttpStatus.CREATED)\n    @PreAuthorize(\"hasRole('OPERACIONES')\")\n    public ArticuloRespuesta crearArticulo(@Valid @RequestBody CrearArticuloSolicitud s) {\n        return ArticuloRespuesta.de(servicio.crearArticulo(s.sku(), s.nombre(), s.unidad(),\n                Boolean.TRUE.equals(s.loteObligatorio()), s.minimo()));\n    }\n\n    /** Da de alta un almacén. */\n    @PostMapping(\"/almacenes\")\n    @ResponseStatus(HttpStatus.CREATED)\n    @PreAuthorize(\"hasRole('ALMACEN')\")\n    public AlmacenRespuesta crearAlmacen(@Valid @RequestBody CrearAlmacenSolicitud s) {\n        return AlmacenRespuesta.de(servicio.crearAlmacen(s.nombre(), s.ubicacion()));\n    }\n\n    /** Registra un movimiento de inventario: entrada, salida, ajuste o reserva. Acepta Idempotency-Key para reintentar sin duplicar el movimiento. */\n    @PostMapping(\"/movimientos\")\n    @PreAuthorize(\"hasRole('ALMACEN')\")\n    public ResponseEntity<?> registrarMovimiento(@RequestHeader(value = Idempotencia.CABECERA, required = false) String clave,\n                                                 @Valid @RequestBody RegistrarMovimientoSolicitud s) {\n        return idempotencia.ejecutar(clave, \"POST /v1/movimientos\", s, HttpStatus.CREATED,\n                () -> MovimientoRespuesta.de(servicio.registrarMovimiento(s.articuloId(), s.almacenId(), s.tipo(),\n                        s.cantidad(), s.lote(), s.referencia())));\n    }\n\n    /** Hasta 15 artículos por debajo de su mínimo, del mayor faltante al menor. */\n    @GetMapping(\"/articulos/bajo-minimo\")\n    @PreAuthorize(\"hasAnyRole('ALMACEN','COMPRAS')\")\n    public List<ArticuloBajoMinimoRespuesta> articulosBajoMinimo() {\n        return servicio.listarBajoMinimo(15).stream().map(ArticuloBajoMinimoRespuesta::de).toList();\n    }\n\n    /** Últimos 15 movimientos de un artículo, del más reciente al más antiguo. */\n    @GetMapping(\"/movimientos\")\n    @PreAuthorize(\"hasAnyRole('ALMACEN','COMPRAS')\")\n    public List<MovimientoRespuesta> movimientosDeArticulo(@RequestParam UUID articulo) {\n        return servicio.movimientosDeArticulo(articulo).stream().map(MovimientoRespuesta::de).toList();\n    }\n\n    /** Devuelve las existencias de un artículo en cada almacén, con lo reservado y lo disponible. */\n    @GetMapping(\"/existencias\")\n    @PreAuthorize(\"hasAnyRole('ALMACEN','COMPRAS','VENTAS')\")\n    public List<ExistenciaRespuesta> existencias(@RequestParam UUID articulo) {\n        return servicio.existenciasDe(articulo).stream().map(ExistenciaRespuesta::de).toList();\n    }\n\n    /** Crea una orden de producción o de servicio. Acepta Idempotency-Key. */\n    @PostMapping(\"/ordenes-operacion\")\n    @ResponseStatus(HttpStatus.CREATED)\n    @PreAuthorize(\"hasRole('OPERACIONES')\")\n    public OrdenRespuesta crearOrden(@Valid @RequestBody CrearOrdenSolicitud s) {\n        return OrdenRespuesta.de(servicio.crearOrden(s.tipo(), s.cantidadObjetivo()));\n    }\n\n    /** Cierra una orden con la cantidad real producida o completada. */\n    @PostMapping(\"/ordenes-operacion/{id}/cierre\")\n    @PreAuthorize(\"hasRole('OPERACIONES')\")\n    public OrdenRespuesta cerrarOrden(@PathVariable UUID id, @Valid @RequestBody CerrarOrdenSolicitud s) {\n        return OrdenRespuesta.de(servicio.cerrarOrden(id, s.cantidadReal()));\n    }\n\n    /** Devuelve los movimientos de un lote, para trazabilidad. */\n    @GetMapping(\"/lotes/{lote}/trazabilidad\")\n    @PreAuthorize(\"hasAnyRole('OPERACIONES','CALIDAD')\")\n    public List<MovimientoRespuesta> trazabilidad(@PathVariable String lote) {\n        return servicio.trazabilidad(lote).stream().map(MovimientoRespuesta::de).toList();\n    }\n\n    /**\n     * Datos para dar de alta un artículo.\n     *\n     * @param sku componente de tipo {@code String}.\n     * @param nombre componente de tipo {@code String}.\n     * @param unidad componente de tipo {@code String}.\n     * @param loteObligatorio componente de tipo {@code Boolean}.\n     * @param minimo componente de tipo {@code BigDecimal}.\n     */\n    public record CrearArticuloSolicitud(\n            @NotBlank @Size(max = 40) String sku,\n            @NotBlank @Size(max = 150) String nombre,\n            @NotBlank @Size(max = 10) String unidad,\n            Boolean loteObligatorio,\n            @DecimalMin(\"0\") BigDecimal minimo) {\n    }\n\n    /**\n     * Datos para dar de alta un almacén.\n     *\n     * @param nombre componente de tipo {@code String}.\n     * @param ubicacion componente de tipo {@code String}.\n     */\n    public record CrearAlmacenSolicitud(@NotBlank @Size(max = 100) String nombre,\n                                        @NotBlank @Size(max = 200) String ubicacion) {\n    }\n\n    /**\n     * Datos de un movimiento: artículo, almacén, tipo, cantidad, lote y referencia.\n     *\n     * @param articuloId componente de tipo {@code UUID}.\n     * @param almacenId componente de tipo {@code UUID}.\n     * @param tipo componente de tipo {@code TipoMovimiento}.\n     * @param cantidad componente de tipo {@code BigDecimal}.\n     * @param lote componente de tipo {@code String}.\n     * @param referencia componente de tipo {@code String}.\n     */\n    public record RegistrarMovimientoSolicitud(\n            @NotNull UUID articuloId,\n            @NotNull UUID almacenId,\n            @NotNull TipoMovimiento tipo,\n            @NotNull @Digits(integer = 9, fraction = 3) BigDecimal cantidad,\n            @Size(max = 60) String lote,\n            @Size(max = 100) String referencia) {\n    }\n\n    /**\n     * Datos para crear una orden: tipo y cantidad objetivo.\n     *\n     * @param tipo componente de tipo {@code TipoOrden}.\n     * @param cantidadObjetivo componente de tipo {@code BigDecimal}.\n     */\n    public record CrearOrdenSolicitud(@NotNull TipoOrden tipo, @NotNull @Digits(integer = 9, fraction = 3) BigDecimal cantidadObjetivo) {\n    }\n\n    /**\n     * Datos para cerrar una orden: cantidad real.\n     *\n     * @param cantidadReal componente de tipo {@code BigDecimal}.\n     */\n    public record CerrarOrdenSolicitud(@NotNull @Digits(integer = 9, fraction = 3) BigDecimal cantidadReal) {\n    }\n\n    /**\n     * Respuesta de un artículo.\n     *\n     * @param id componente de tipo {@code UUID}.\n     * @param sku componente de tipo {@code String}.\n     * @param nombre componente de tipo {@code String}.\n     * @param unidad componente de tipo {@code String}.\n     * @param loteObligatorio componente de tipo {@code boolean}.\n     * @param minimo componente de tipo {@code BigDecimal}.\n     */\n    public record ArticuloRespuesta(UUID id, String sku, String nombre, String unidad, boolean loteObligatorio,\n                                    BigDecimal minimo) {\n        /** Convierte un artículo en su respuesta. */\n        static ArticuloRespuesta de(Articulo a) {\n            return new ArticuloRespuesta(a.getId(), a.getSku(), a.getNombre(), a.getUnidad(),\n                    a.isLoteObligatorio(), a.getMinimo());\n        }\n    }\n\n    /**\n     * Respuesta de un almacén.\n     *\n     * @param id componente de tipo {@code UUID}.\n     * @param nombre componente de tipo {@code String}.\n     * @param ubicacion componente de tipo {@code String}.\n     */\n    public record AlmacenRespuesta(UUID id, String nombre, String ubicacion) {\n        /** Convierte un almacén en su respuesta. */\n        static AlmacenRespuesta de(Almacen a) {\n            return new AlmacenRespuesta(a.getId(), a.getNombre(), a.getUbicacion());\n        }\n    }\n\n    /**\n     * Respuesta de un movimiento.\n     *\n     * @param id componente de tipo {@code UUID}.\n     * @param articuloId componente de tipo {@code UUID}.\n     * @param almacenId componente de tipo {@code UUID}.\n     * @param tipo componente de tipo {@code TipoMovimiento}.\n     * @param cantidad componente de tipo {@code BigDecimal}.\n     * @param lote componente de tipo {@code String}.\n     * @param referencia componente de tipo {@code String}.\n     * @param creadoUtc componente de tipo {@code Instant}.\n     */\n    public record MovimientoRespuesta(UUID id, UUID articuloId, UUID almacenId, TipoMovimiento tipo,\n                                      BigDecimal cantidad, String lote, String referencia, Instant creadoUtc) {\n        /** Convierte un movimiento en su respuesta. */\n        static MovimientoRespuesta de(MovimientoInventario m) {\n            return new MovimientoRespuesta(m.getId(), m.getArticuloId(), m.getAlmacenId(), m.getTipo(),\n                    m.getCantidad(), m.getLote(), m.getReferencia(), m.getCreadoUtc());\n        }\n    }\n\n    /**\n     * Respuesta de un artículo que está por debajo de su mínimo.\n     *\n     * @param articuloId componente de tipo {@code UUID}.\n     * @param sku componente de tipo {@code String}.\n     * @param nombre componente de tipo {@code String}.\n     * @param unidad componente de tipo {@code String}.\n     * @param minimo componente de tipo {@code BigDecimal}.\n     * @param existencia componente de tipo {@code BigDecimal}.\n     * @param faltante componente de tipo {@code BigDecimal}.\n     */\n    public record ArticuloBajoMinimoRespuesta(UUID articuloId, String sku, String nombre, String unidad,\n                                              BigDecimal minimo, BigDecimal existencia, BigDecimal faltante) {\n        /** Convierte el resultado de la consulta en su respuesta. */\n        static ArticuloBajoMinimoRespuesta de(com.mx.josesaid.develop.inventario.domain.ArticuloBajoMinimo r) {\n            return new ArticuloBajoMinimoRespuesta(r.articuloId(), r.sku(), r.nombre(), r.unidad(), r.minimo(),\n                    r.existencia(), r.faltante());\n        }\n    }\n\n    /**\n     * Respuesta de la existencia de un artículo en un almacén.\n     *\n     * @param almacenId componente de tipo {@code UUID}.\n     * @param cantidad componente de tipo {@code BigDecimal}.\n     * @param reservado componente de tipo {@code BigDecimal}.\n     * @param disponible componente de tipo {@code BigDecimal}.\n     */\n    public record ExistenciaRespuesta(UUID almacenId, BigDecimal cantidad, BigDecimal reservado, BigDecimal disponible) {\n        /** Convierte una existencia en su respuesta, con el disponible calculado. */\n        static ExistenciaRespuesta de(Existencia e) {\n            return new ExistenciaRespuesta(e.getAlmacenId(), e.getCantidad(), e.getReservado(), e.disponible());\n        }\n    }\n\n    /**\n     * Respuesta de una orden de operación.\n     *\n     * @param id componente de tipo {@code UUID}.\n     * @param tipo componente de tipo {@code TipoOrden}.\n     * @param estatus componente de tipo {@code EstatusOrden}.\n     * @param cantidadObjetivo componente de tipo {@code BigDecimal}.\n     * @param cantidadReal componente de tipo {@code BigDecimal}.\n     */\n    public record OrdenRespuesta(UUID id, TipoOrden tipo, EstatusOrden estatus, BigDecimal cantidadObjetivo,\n                                 BigDecimal cantidadReal) {\n        /** Convierte una orden en su respuesta. */\n        static OrdenRespuesta de(OrdenOperacion o) {\n            return new OrdenRespuesta(o.getId(), o.getTipo(), o.getEstatus(), o.getCantidadObjetivo(),\n                    o.getCantidadReal());\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/api/ManejadorErrores.java": "package com.mx.josesaid.develop.inventario.api;\n\nimport com.mx.josesaid.develop.inventario.domain.ConflictoException;\nimport com.mx.josesaid.develop.inventario.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.inventario.domain.ReglaDeNegocioException;\nimport com.mx.josesaid.develop.inventario.domain.SolicitudInvalidaException;\nimport java.net.URI;\nimport java.util.stream.Collectors;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.ProblemDetail;\nimport org.springframework.orm.ObjectOptimisticLockingFailureException;\nimport org.springframework.web.bind.MethodArgumentNotValidException;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\n\n/** Errores RFC 9457 con type {@code urn:josesaid:inventario-operaciones:error:<slug>}. */\n@RestControllerAdvice\npublic class ManejadorErrores {\n\n    private static final String PREFIJO = \"urn:josesaid:inventario-operaciones:error:\";\n\n    /** Convierte un recurso inexistente en un problema HTTP. */\n    @ExceptionHandler(RecursoNoEncontradoException.class)\n    ProblemDetail noEncontrado(RecursoNoEncontradoException ex) {\n        return problema(HttpStatus.NOT_FOUND, \"no-encontrado\", ex.getMessage());\n    }\n\n    /** Convierte un conflicto, por ejemplo existencia insuficiente, en un problema HTTP. */\n    @ExceptionHandler(ConflictoException.class)\n    ProblemDetail conflicto(ConflictoException ex) {\n        return problema(HttpStatus.CONFLICT, \"conflicto\", ex.getMessage());\n    }\n\n    /** Convierte un conflicto de concurrencia (dos cambios al mismo registro) en un problema HTTP. El cliente debe reintentar. */\n    @ExceptionHandler(ObjectOptimisticLockingFailureException.class)\n    ProblemDetail concurrencia(ObjectOptimisticLockingFailureException ex) {\n        return problema(HttpStatus.CONFLICT, \"conflicto-concurrencia\",\n                \"La existencia cambió mientras se procesaba. Vuelva a intentarlo.\");\n    }\n\n    /** Convierte una regla de negocio incumplida en un problema HTTP. */\n    @ExceptionHandler(ReglaDeNegocioException.class)\n    ProblemDetail reglaDeNegocio(ReglaDeNegocioException ex) {\n        return problema(HttpStatus.UNPROCESSABLE_ENTITY, \"regla-de-negocio\", ex.getMessage());\n    }\n\n    /** Convierte una solicitud inválida en un problema HTTP. */\n    @ExceptionHandler(SolicitudInvalidaException.class)\n    ProblemDetail solicitudInvalida(SolicitudInvalidaException ex) {\n        return problema(HttpStatus.BAD_REQUEST, \"datos-invalidos\", ex.getMessage());\n    }\n\n    /** Convierte errores de validación de los datos recibidos en un problema HTTP con el detalle de cada campo. */\n    @ExceptionHandler(MethodArgumentNotValidException.class)\n    ProblemDetail validacion(MethodArgumentNotValidException ex) {\n        String detalle = ex.getBindingResult().getFieldErrors().stream()\n                .map(e -> e.getField() + \": \" + e.getDefaultMessage())\n                .collect(Collectors.joining(\"; \"));\n        return problema(HttpStatus.BAD_REQUEST, \"datos-invalidos\", detalle);\n    }\n\n    /** Construye la respuesta de error con su estatus, código y detalle. */\n    private static ProblemDetail problema(HttpStatus estatus, String slug, String detalle) {\n        ProblemDetail pd = ProblemDetail.forStatusAndDetail(estatus, detalle);\n        pd.setType(URI.create(PREFIJO + slug));\n        pd.setTitle(estatus.getReasonPhrase());\n        return pd;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/application/EventoDominio.java": "package com.mx.josesaid.develop.inventario.application;\n\nimport java.util.Map;\n\n/**\n * Evento de negocio. Se guarda en el outbox y luego se envía a Kafka.\n *\n * @param tipo componente de tipo {@code String}.\n * @param agregadoId componente de tipo {@code String}.\n * @param datos componente de tipo {@code Map<String, Object>}.\n */\npublic record EventoDominio(String tipo, String agregadoId, Map<String, Object> datos) {\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/application/InventarioService.java": "package com.mx.josesaid.develop.inventario.application;\n\nimport com.mx.josesaid.develop.inventario.domain.Almacen;\nimport com.mx.josesaid.develop.inventario.domain.AlmacenRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.Articulo;\nimport com.mx.josesaid.develop.inventario.domain.ArticuloBajoMinimo;\nimport com.mx.josesaid.develop.inventario.domain.ArticuloRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.ConflictoException;\nimport com.mx.josesaid.develop.inventario.domain.Existencia;\nimport com.mx.josesaid.develop.inventario.domain.ExistenciaRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoInventario;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.OrdenOperacion;\nimport com.mx.josesaid.develop.inventario.domain.OrdenRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.inventario.domain.SolicitudInvalidaException;\nimport com.mx.josesaid.develop.inventario.domain.TipoMovimiento;\nimport com.mx.josesaid.develop.inventario.domain.TipoOrden;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/** Casos de uso de inventario y operaciones. Los eventos se guardan en el outbox en la misma transacción. */\n@Service\npublic class InventarioService {\n\n    public static final String EVENTO_BAJO_MINIMO = \"existencia-bajo-minimo\";\n    public static final String EVENTO_ORDEN_CERRADA = \"orden-operacion-cerrada\";\n\n    private final ArticuloRepositorio articulos;\n    private final AlmacenRepositorio almacenes;\n    private final ExistenciaRepositorio existencias;\n    private final MovimientoRepositorio movimientos;\n    private final OrdenRepositorio ordenes;\n    private final PublicadorEventos eventos;\n    private final Clock reloj;\n\n    /** Recibe los repositorios de artículos, almacenes, existencias, movimientos y órdenes, y el reloj. */\n    public InventarioService(ArticuloRepositorio articulos, AlmacenRepositorio almacenes,\n                             ExistenciaRepositorio existencias, MovimientoRepositorio movimientos,\n                             OrdenRepositorio ordenes, PublicadorEventos eventos, Clock reloj) {\n        this.articulos = articulos;\n        this.almacenes = almacenes;\n        this.existencias = existencias;\n        this.movimientos = movimientos;\n        this.ordenes = ordenes;\n        this.eventos = eventos;\n        this.reloj = reloj;\n    }\n\n    /** Da de alta un artículo. Valida el SKU y que no exista ya. */\n    @Transactional\n    public Articulo crearArticulo(String sku, String nombre, String unidad, boolean loteObligatorio, BigDecimal minimo) {\n        if (sku != null && articulos.existePorSku(sku.trim())) {\n            throw new ConflictoException(\"Ya existe el artículo con SKU \" + sku.trim());\n        }\n        return articulos.guardar(Articulo.crear(sku, nombre, unidad, loteObligatorio, minimo));\n    }\n\n    /** Da de alta un almacén. */\n    @Transactional\n    public Almacen crearAlmacen(String nombre, String ubicacion) {\n        return almacenes.guardar(Almacen.crear(nombre, ubicacion));\n    }\n\n    /**\n     * Registra un movimiento. Orden de validación: artículo y almacén existen (404), lote obligatorio (400),\n     * reglas de existencia (409 o 422). Si la existencia queda bajo el mínimo, publica un evento.\n     */\n    @Transactional\n    public MovimientoInventario registrarMovimiento(UUID articuloId, UUID almacenId, TipoMovimiento tipo,\n                                                    BigDecimal cantidad, String lote, String referencia) {\n        Articulo articulo = obtenerArticulo(articuloId);\n        obtenerAlmacen(almacenId);\n        if (articulo.isLoteObligatorio() && (lote == null || lote.isBlank())) {\n            throw new SolicitudInvalidaException(\"El artículo \" + articulo.getSku() + \" requiere lote\");\n        }\n        Existencia existencia = existencias.buscar(articuloId, almacenId)\n                .orElseGet(() -> Existencia.vacia(articuloId, almacenId));\n        existencia.aplicar(tipo, cantidad);\n        existencias.guardar(existencia);\n\n        MovimientoInventario movimiento = movimientos.guardar(\n                MovimientoInventario.crear(articuloId, almacenId, tipo, cantidad, lote, referencia, Instant.now(reloj)));\n\n        boolean reduceExistencia = tipo == TipoMovimiento.SALIDA || tipo == TipoMovimiento.AJUSTE;\n        if (reduceExistencia && articulo.getMinimo().signum() > 0\n                && existencia.getCantidad().compareTo(articulo.getMinimo()) < 0) {\n            eventos.publicar(new EventoDominio(EVENTO_BAJO_MINIMO, articuloId.toString(), Map.of(\n                    \"articulo_id\", articuloId.toString(),\n                    \"almacen_id\", almacenId.toString(),\n                    \"cantidad\", existencia.getCantidad().toPlainString())));\n        }\n        return movimiento;\n    }\n\n    /** Crea una orden de operación en estatus abierta. */\n    @Transactional\n    public OrdenOperacion crearOrden(TipoOrden tipo, BigDecimal cantidadObjetivo) {\n        return ordenes.guardar(OrdenOperacion.crear(tipo, cantidadObjetivo));\n    }\n\n    /** Cierra una orden con su cantidad real y guarda el cambio. */\n    @Transactional\n    public OrdenOperacion cerrarOrden(UUID id, BigDecimal cantidadReal) {\n        OrdenOperacion orden = ordenes.buscarPorId(id)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Orden no encontrada: \" + id));\n        orden.cerrar(cantidadReal);\n        OrdenOperacion guardada = ordenes.guardar(orden);\n        eventos.publicar(new EventoDominio(EVENTO_ORDEN_CERRADA, id.toString(), Map.of(\n                \"id\", id.toString(),\n                \"cantidad_real\", guardada.getCantidadReal().toPlainString())));\n        return guardada;\n    }\n\n    /**\n     * Artículos cuya existencia total (cantidad, sin restar reservas) está por debajo de su mínimo.\n     * Los de mayor faltante primero. Mismo criterio que el evento existencia-bajo-minimo.\n     */\n    @Transactional(readOnly = true)\n    public List<ArticuloBajoMinimo> listarBajoMinimo(int limite) {\n        Map<UUID, BigDecimal> totales = existencias.cantidadTotalPorArticulo();\n        return articulos.listarConMinimo().stream()\n                .map(a -> {\n                    BigDecimal existencia = totales.getOrDefault(a.getId(), BigDecimal.ZERO);\n                    return new ArticuloBajoMinimo(a.getId(), a.getSku(), a.getNombre(), a.getUnidad(),\n                            a.getMinimo(), existencia, a.getMinimo().subtract(existencia));\n                })\n                .filter(r -> r.existencia().compareTo(r.minimo()) < 0)\n                .sorted(java.util.Comparator.comparing(ArticuloBajoMinimo::faltante).reversed())\n                .limit(limite)\n                .toList();\n    }\n\n    /** Últimos 15 movimientos de un artículo, del más reciente al más antiguo. */\n    @Transactional(readOnly = true)\n    public List<MovimientoInventario> movimientosDeArticulo(UUID articuloId) {\n        articulos.buscarPorId(articuloId)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Artículo no encontrado: \" + articuloId));\n        return movimientos.listarRecientesDeArticulo(articuloId, 15);\n    }\n\n    /** Devuelve las existencias de un artículo en todos sus almacenes. */\n    @Transactional(readOnly = true)\n    public List<Existencia> existenciasDe(UUID articuloId) {\n        obtenerArticulo(articuloId);\n        return existencias.buscarPorArticulo(articuloId);\n    }\n\n    /** Devuelve los movimientos de un lote. */\n    @Transactional(readOnly = true)\n    public List<MovimientoInventario> trazabilidad(String lote) {\n        List<MovimientoInventario> resultado = movimientos.buscarPorLote(lote);\n        if (resultado.isEmpty()) {\n            throw new RecursoNoEncontradoException(\"No hay movimientos para el lote \" + lote);\n        }\n        return resultado;\n    }\n\n    /** Devuelve un artículo por id o lanza RecursoNoEncontradoException. */\n    private Articulo obtenerArticulo(UUID id) {\n        return articulos.buscarPorId(id)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Artículo no encontrado: \" + id));\n    }\n\n    /** Devuelve un almacén por id o lanza RecursoNoEncontradoException. */\n    private Almacen obtenerAlmacen(UUID id) {\n        return almacenes.buscarPorId(id)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Almacén no encontrado: \" + id));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/application/PublicadorEventos.java": "package com.mx.josesaid.develop.inventario.application;\n\n/** Publica eventos de dominio de inventario para que otros servicios reaccionen. */\npublic interface PublicadorEventos {\n    void publicar(EventoDominio evento);\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/application/RecepcionesService.java": "package com.mx.josesaid.develop.inventario.application;\n\nimport com.mx.josesaid.develop.inventario.domain.Articulo;\nimport com.mx.josesaid.develop.inventario.domain.ArticuloRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.Existencia;\nimport com.mx.josesaid.develop.inventario.domain.ExistenciaRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoInventario;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.RecepcionesRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.TipoMovimiento;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Suma a las existencias lo recibido de una orden de compra. Cada recepción se aplica una sola vez.\n * Los artículos con lote obligatorio no se registran: el evento de compras no trae lote.\n */\n@Service\npublic class RecepcionesService {\n\n    private static final Logger log = LoggerFactory.getLogger(RecepcionesService.class);\n\n    /**\n     * Línea recibida: SKU del artículo y cantidad.\n     *\n     * @param sku componente de tipo {@code String}.\n     * @param cantidad componente de tipo {@code BigDecimal}.\n     */\n    public record LineaRecibida(String sku, BigDecimal cantidad) {\n    }\n\n    private final ArticuloRepositorio articulos;\n    private final ExistenciaRepositorio existencias;\n    private final MovimientoRepositorio movimientos;\n    private final RecepcionesRepositorio recepciones;\n    private final Clock reloj;\n\n    /** Recibe los repositorios, el reloj y el registro de recepciones ya aplicadas. */\n    public RecepcionesService(ArticuloRepositorio articulos, ExistenciaRepositorio existencias,\n                              MovimientoRepositorio movimientos, RecepcionesRepositorio recepciones, Clock reloj) {\n        this.articulos = articulos;\n        this.existencias = existencias;\n        this.movimientos = movimientos;\n        this.recepciones = recepciones;\n        this.reloj = reloj;\n    }\n\n    /** Suma a las existencias lo recibido de una orden de compra. Cada recepción se aplica una sola vez, aunque el evento llegue dos veces. Los artículos con lote obligatorio no se registran, porque el evento no trae lote. */\n    @Transactional\n    public void registrar(UUID eventoId, UUID ordenId, UUID almacenId, List<LineaRecibida> lineas) {\n        if (!recepciones.marcarProcesada(eventoId)) {\n            return;\n        }\n        Instant ahora = Instant.now(reloj);\n        for (LineaRecibida linea : lineas) {\n            Optional<Articulo> encontrado = articulos.buscarPorSku(linea.sku());\n            if (encontrado.isEmpty()) {\n                log.warn(\"Orden {}: el SKU {} no existe en inventario; no se registra la entrada\", ordenId, linea.sku());\n                continue;\n            }\n            Articulo articulo = encontrado.get();\n            if (articulo.isLoteObligatorio()) {\n                log.error(\"Orden {}: el artículo {} requiere lote y el evento no lo trae; no se registra la entrada\",\n                        ordenId, linea.sku());\n                continue;\n            }\n            Existencia existencia = existencias.buscar(articulo.getId(), almacenId)\n                    .orElseGet(() -> Existencia.vacia(articulo.getId(), almacenId));\n            existencia.aplicar(TipoMovimiento.ENTRADA, linea.cantidad());\n            existencias.guardar(existencia);\n            movimientos.guardar(MovimientoInventario.crear(articulo.getId(), almacenId, TipoMovimiento.ENTRADA,\n                    linea.cantidad(), null, \"Recepción orden \" + ordenId, ahora));\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/application/ReservasPedidoService.java": "package com.mx.josesaid.develop.inventario.application;\n\nimport com.mx.josesaid.develop.inventario.domain.ArticuloRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.Existencia;\nimport com.mx.josesaid.develop.inventario.domain.ExistenciaRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoInventario;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.ReservasPedidoRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.ReservasPedidoRepositorio.Reserva;\nimport com.mx.josesaid.develop.inventario.domain.TipoMovimiento;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.UUID;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Reserva las piezas de un pedido al confirmarlo y las descuenta al entregarlo.\n * Si al confirmar no alcanza la existencia, se reserva lo disponible y el faltante queda en el log.\n * Cada evento se aplica una sola vez, aunque Kafka lo reentregue.\n */\n@Service\npublic class ReservasPedidoService {\n\n    public static final String EVENTO_CONFIRMADO = \"PedidoConfirmado\";\n    public static final String EVENTO_ENTREGADO = \"PedidoEntregado\";\n\n    private static final Logger log = LoggerFactory.getLogger(ReservasPedidoService.class);\n\n    /**\n     * Línea de un pedido: artículo y cantidad a reservar.\n     *\n     * @param articuloId componente de tipo {@code UUID}.\n     * @param cantidad componente de tipo {@code BigDecimal}.\n     */\n    public record LineaPedido(UUID articuloId, BigDecimal cantidad) {\n    }\n\n    private final ArticuloRepositorio articulos;\n    private final ExistenciaRepositorio existencias;\n    private final MovimientoRepositorio movimientos;\n    private final ReservasPedidoRepositorio reservas;\n    private final Clock reloj;\n\n    /** Recibe los repositorios de artículos, existencias, movimientos y reservas, y el reloj. */\n    public ReservasPedidoService(ArticuloRepositorio articulos, ExistenciaRepositorio existencias,\n                                 MovimientoRepositorio movimientos, ReservasPedidoRepositorio reservas, Clock reloj) {\n        this.articulos = articulos;\n        this.existencias = existencias;\n        this.movimientos = movimientos;\n        this.reservas = reservas;\n        this.reloj = reloj;\n    }\n\n    /** Reserva las piezas de un pedido confirmado. Si no alcanza la existencia, reserva lo disponible y registra el faltante. Cada pedido se procesa una sola vez. */\n    @Transactional\n    public void reservar(UUID pedidoId, UUID almacenId, List<LineaPedido> lineas) {\n        if (!reservas.marcarProcesado(pedidoId, EVENTO_CONFIRMADO)) {\n            return;\n        }\n        Instant ahora = Instant.now(reloj);\n        for (LineaPedido linea : lineas) {\n            if (articulos.buscarPorId(linea.articuloId()).isEmpty()) {\n                log.warn(\"Pedido {}: el artículo {} no existe en inventario; no se reserva\", pedidoId, linea.articuloId());\n                continue;\n            }\n            Existencia existencia = existencias.buscar(linea.articuloId(), almacenId)\n                    .orElseGet(() -> Existencia.vacia(linea.articuloId(), almacenId));\n            BigDecimal pedida = linea.cantidad();\n            BigDecimal aReservar = pedida.min(existencia.disponible().max(BigDecimal.ZERO));\n            if (aReservar.signum() > 0) {\n                existencia.aplicar(TipoMovimiento.RESERVA, aReservar);\n                existencias.guardar(existencia);\n                movimientos.guardar(MovimientoInventario.crear(linea.articuloId(), almacenId, TipoMovimiento.RESERVA,\n                        aReservar, null, \"Pedido \" + pedidoId, ahora));\n                reservas.guardarReserva(pedidoId, linea.articuloId(), almacenId, aReservar);\n            }\n            if (aReservar.compareTo(pedida) < 0) {\n                log.warn(\"Pedido {}: artículo {} sin existencia suficiente; pedido {}, reservado {}\",\n                        pedidoId, linea.articuloId(), pedida.toPlainString(), aReservar.toPlainString());\n            }\n        }\n    }\n\n    /** Descuenta del inventario lo reservado al entregarse el pedido y libera esas reservas. Si el pedido no tiene reservas, no hace nada. */\n    @Transactional\n    public void entregar(UUID pedidoId) {\n        if (!reservas.marcarProcesado(pedidoId, EVENTO_ENTREGADO)) {\n            return;\n        }\n        List<Reserva> pendientes = reservas.reservasDe(pedidoId);\n        if (pendientes.isEmpty()) {\n            log.info(\"Pedido {} entregado sin reservas registradas; no hay existencias que descontar\", pedidoId);\n            return;\n        }\n        Instant ahora = Instant.now(reloj);\n        for (Reserva reserva : pendientes) {\n            Existencia existencia = existencias.buscar(reserva.articuloId(), reserva.almacenId())\n                    .orElseThrow(() -> new IllegalStateException(\n                            \"Existencia inexistente para la reserva del pedido \" + pedidoId));\n            existencia.liberarReserva(reserva.cantidad());\n            existencia.aplicar(TipoMovimiento.SALIDA, reserva.cantidad());\n            existencias.guardar(existencia);\n            movimientos.guardar(MovimientoInventario.crear(reserva.articuloId(), reserva.almacenId(),\n                    TipoMovimiento.SALIDA, reserva.cantidad(), null, \"Pedido \" + pedidoId, ahora));\n        }\n        reservas.eliminarReservas(pedidoId);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/config/PropiedadesJwt.java": "package com.mx.josesaid.develop.inventario.config;\n\nimport java.time.Duration;\nimport org.springframework.boot.context.properties.ConfigurationProperties;\n\n/**\n * Propiedades del emisor de tokens, enlazadas desde {@code inventario.jwt}.\n *\n * @param jwksUri URL del JWKS de usuarios-accesos-ms con la clave pública para validar tokens\n * @param duracion vida del token de acceso\n * @param emisor   valor del claim {@code iss}\n */\n@ConfigurationProperties(prefix = \"inventario.jwt\")\npublic record PropiedadesJwt(String jwksUri, Duration duracion, String emisor) {\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/config/RelojConfig.java": "package com.mx.josesaid.develop.inventario.config;\n\nimport java.time.Clock;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/** Reloj en UTC. Inyectarlo permite probar las reglas de tiempo sin depender de la hora real. */\n@Configuration\npublic class RelojConfig {\n\n    /** Reloj del sistema en UTC, usado para todas las fechas de inventario. */\n    @Bean\n    Clock reloj() {\n        return Clock.systemUTC();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/config/SeguridadConfig.java": "package com.mx.josesaid.develop.inventario.config;\n\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchy;\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchyImpl;\n\nimport com.mx.josesaid.develop.inventario.seguridad.EntradaNoAutorizada;\n\nimport com.mx.josesaid.develop.inventario.seguridad.RevocacionSesiones;\nimport com.mx.josesaid.develop.inventario.seguridad.ValidadorRevocacion;\nimport org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;\nimport org.springframework.security.oauth2.jwt.JwtValidators;\n\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;\nimport org.springframework.security.crypto.password.PasswordEncoder;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.security.oauth2.jwt.NimbusJwtDecoder;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter;\nimport org.springframework.security.web.SecurityFilterChain;\n\n/**\n * Seguridad del servicio: API sin estado, JWT como resource server y autorización por rol.\n *\n * <p>Solo el login y el health son públicos. Todo lo demás exige un token válido.\n */\n@Configuration\n@EnableWebSecurity\n@EnableMethodSecurity\npublic class SeguridadConfig {\n\n    /** Cadena de seguridad de la API sin estado. Exige JWT válido en todo, excepto salud, info y métricas. */\n    @Bean\n    SecurityFilterChain cadenaSeguridad(HttpSecurity http) throws Exception {\n        http\n            .csrf(csrf -> csrf.disable()) // API sin cookies de sesión: no aplica CSRF\n            .sessionManagement(sesion -> sesion.sessionCreationPolicy(SessionCreationPolicy.STATELESS))\n            .authorizeHttpRequests(auth -> auth\n                .requestMatchers(\"/actuator/health\", \"/actuator/health/**\", \"/actuator/prometheus\").permitAll()\n                .anyRequest().authenticated())\n            .oauth2ResourceServer(oauth -> oauth.authenticationEntryPoint(new EntradaNoAutorizada()).jwt(jwt -> jwt.jwtAuthenticationConverter(convertidorJwt())));\n        return http.build();\n    }\n\n    /** Convierte el claim {@code roles} en autoridades {@code ROLE_*}. */\n    @Bean\n    JwtAuthenticationConverter convertidorJwt() {\n        JwtGrantedAuthoritiesConverter autoridades = new JwtGrantedAuthoritiesConverter();\n        autoridades.setAuthoritiesClaimName(\"roles\");\n        autoridades.setAuthorityPrefix(\"ROLE_\");\n        JwtAuthenticationConverter convertidor = new JwtAuthenticationConverter();\n        convertidor.setJwtGrantedAuthoritiesConverter(autoridades);\n        return convertidor;\n    }\n\n    /** Valida la firma con la clave pública que publica usuarios-accesos-ms (JWKS). */\n    @Bean\n    JwtDecoder jwtDecoder(PropiedadesJwt propiedades, RevocacionSesiones revocaciones) {\n        var decoder = NimbusJwtDecoder.withJwkSetUri(propiedades.jwksUri()).build();\n        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefault(),\n                new ValidadorRevocacion(revocaciones)));\n        return decoder;\n    }\n\n    /** Codificador de contraseñas BCrypt. */\n    @Bean\n    PasswordEncoder passwordEncoder() {\n        return new BCryptPasswordEncoder();\n    }\n\n    /** ADMIN puede hacer todo: hereda todos los roles de negocio. */\n    @Bean\n    RoleHierarchy jerarquiaRoles() {\n        return RoleHierarchyImpl.withDefaultRolePrefix()\n                .role(\"ADMIN\").implies(\"FINANZAS\", \"CONTADOR\", \"VENTAS\", \"COMPRAS\", \"ALMACEN\", \"OPERACIONES\", \"CALIDAD\", \"DIRECCION\", \"LEGAL\", \"JEFE_AREA\")\n                .build();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/Almacen.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport java.util.UUID;\n\n/** Lugar físico donde se guardan los artículos. */\npublic class Almacen {\n\n    private final UUID id;\n    private final String nombre;\n    private final String ubicacion;\n\n    /** Constructor privado: los almacenes se crean con sus fábricas. */\n    private Almacen(UUID id, String nombre, String ubicacion) {\n        this.id = id;\n        this.nombre = nombre;\n        this.ubicacion = ubicacion;\n    }\n\n    /** Crea un almacén nuevo con id generado. Valida el nombre. */\n    public static Almacen crear(String nombre, String ubicacion) {\n        if (nombre == null || nombre.isBlank()) {\n            throw new ReglaDeNegocioException(\"El nombre del almacén es obligatorio\");\n        }\n        if (ubicacion == null || ubicacion.isBlank()) {\n            throw new ReglaDeNegocioException(\"La ubicación del almacén es obligatoria\");\n        }\n        return new Almacen(UUID.randomUUID(), nombre.trim(), ubicacion.trim());\n    }\n\n    /** Reconstruye un almacén desde la base de datos sin aplicar reglas. */\n    public static Almacen reconstruir(UUID id, String nombre, String ubicacion) {\n        return new Almacen(id, nombre, ubicacion);\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el nombre. */\n    public String getNombre() { return nombre; }\n    /** Devuelve la ubicación. */\n    public String getUbicacion() { return ubicacion; }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/AlmacenRepositorio.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto para guardar y consultar almacenes, sin depender de JPA. */\npublic interface AlmacenRepositorio {\n    Almacen guardar(Almacen almacen);\n    Optional<Almacen> buscarPorId(UUID id);\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/Articulo.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport java.math.BigDecimal;\nimport java.util.UUID;\n\n/** Artículo del catálogo. Si requiere lote, todo movimiento debe indicarlo. */\npublic class Articulo {\n\n    private final UUID id;\n    private final String sku;\n    private final String nombre;\n    private final String unidad;\n    private final boolean loteObligatorio;\n    private final BigDecimal minimo;\n\n    /** Constructor privado: los artículos se crean con sus fábricas. */\n    private Articulo(UUID id, String sku, String nombre, String unidad, boolean loteObligatorio, BigDecimal minimo) {\n        this.id = id;\n        this.sku = sku;\n        this.nombre = nombre;\n        this.unidad = unidad;\n        this.loteObligatorio = loteObligatorio;\n        this.minimo = minimo;\n    }\n\n    /** Crea un artículo nuevo. Valida SKU, nombre, unidad y mínimo. */\n    public static Articulo crear(String sku, String nombre, String unidad, boolean loteObligatorio, BigDecimal minimo) {\n        if (sku == null || sku.isBlank() || sku.length() > 40) {\n            throw new ReglaDeNegocioException(\"El SKU es obligatorio (máximo 40 caracteres)\");\n        }\n        if (nombre == null || nombre.isBlank()) {\n            throw new ReglaDeNegocioException(\"El nombre del artículo es obligatorio\");\n        }\n        if (unidad == null || unidad.isBlank() || unidad.length() > 10) {\n            throw new ReglaDeNegocioException(\"La unidad de medida es obligatoria (máximo 10 caracteres)\");\n        }\n        BigDecimal min = minimo == null ? BigDecimal.ZERO : minimo;\n        if (min.signum() < 0) {\n            throw new ReglaDeNegocioException(\"El mínimo no puede ser negativo\");\n        }\n        return new Articulo(UUID.randomUUID(), sku.trim(), nombre.trim(), unidad.trim(), loteObligatorio,\n                min.setScale(3, java.math.RoundingMode.HALF_EVEN));\n    }\n\n    /** Reconstruye un artículo desde la base de datos sin aplicar reglas. */\n    public static Articulo reconstruir(UUID id, String sku, String nombre, String unidad, boolean loteObligatorio,\n                                       BigDecimal minimo) {\n        return new Articulo(id, sku, nombre, unidad, loteObligatorio, minimo);\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el SKU. */\n    public String getSku() { return sku; }\n    /** Devuelve el nombre. */\n    public String getNombre() { return nombre; }\n    /** Devuelve la unidad de medida. */\n    public String getUnidad() { return unidad; }\n    /** Indica si el artículo exige lote en cada movimiento. */\n    public boolean isLoteObligatorio() { return loteObligatorio; }\n    /** Devuelve la existencia mínima; por debajo de ella el artículo aparece en alertas. */\n    public BigDecimal getMinimo() { return minimo; }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/ArticuloBajoMinimo.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport java.math.BigDecimal;\nimport java.util.UUID;\n\n/**\n * Artículo cuya existencia total está por debajo de su mínimo. Faltante = mínimo menos existencia.\n *\n * @param articuloId componente de tipo {@code UUID}.\n * @param sku componente de tipo {@code String}.\n * @param nombre componente de tipo {@code String}.\n * @param unidad componente de tipo {@code String}.\n * @param minimo componente de tipo {@code BigDecimal}.\n * @param existencia componente de tipo {@code BigDecimal}.\n * @param faltante componente de tipo {@code BigDecimal}.\n */\npublic record ArticuloBajoMinimo(UUID articuloId, String sku, String nombre, String unidad, BigDecimal minimo,\n                                 BigDecimal existencia, BigDecimal faltante) {\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/ArticuloRepositorio.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto para guardar y consultar artículos, sin depender de JPA. */\npublic interface ArticuloRepositorio {\n    Articulo guardar(Articulo articulo);\n    Optional<Articulo> buscarPorId(UUID id);\n    boolean existePorSku(String sku);\n    Optional<Articulo> buscarPorSku(String sku);\n\n    /** Artículos con mínimo mayor a cero. */\n    java.util.List<Articulo> listarConMinimo();\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/ConflictoException.java": "package com.mx.josesaid.develop.inventario.domain;\n\n/** Conflicto con el estado actual, por ejemplo existencia insuficiente. HTTP 409. */\npublic class ConflictoException extends RuntimeException {\n    /** Se lanza cuando la operación choca con el estado actual, por ejemplo por falta de existencia. Se responde como conflicto. */\n    public ConflictoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/EstatusOrden.java": "package com.mx.josesaid.develop.inventario.domain;\n\n/** Estatus de una orden: abierta o cerrada. */\npublic enum EstatusOrden { ABIERTA, CERRADA }\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/Existencia.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport static java.math.BigDecimal.ZERO;\n\nimport java.math.BigDecimal;\nimport java.util.UUID;\n\n/**\n * Existencia de un artículo en un almacén. Reglas: nunca negativa, lo reservado nunca supera\n * lo existente y una salida o reserva no puede exceder lo disponible (existencia menos reserva).\n */\npublic class Existencia {\n\n    private final UUID articuloId;\n    private final UUID almacenId;\n    private BigDecimal cantidad;\n    private BigDecimal reservado;\n\n    /** Constructor privado: las existencias se crean con sus fábricas. */\n    private Existencia(UUID articuloId, UUID almacenId, BigDecimal cantidad, BigDecimal reservado) {\n        this.articuloId = articuloId;\n        this.almacenId = almacenId;\n        this.cantidad = cantidad;\n        this.reservado = reservado;\n    }\n\n    /** Crea una existencia en cero para un artículo en un almacén. */\n    public static Existencia vacia(UUID articuloId, UUID almacenId) {\n        return new Existencia(articuloId, almacenId, ZERO, ZERO);\n    }\n\n    /** Reconstruye una existencia desde la base de datos sin aplicar reglas. */\n    public static Existencia reconstruir(UUID articuloId, UUID almacenId, BigDecimal cantidad, BigDecimal reservado) {\n        return new Existencia(articuloId, almacenId, cantidad, reservado);\n    }\n\n    /** Aplica un movimiento. Valida cantidad y reglas de existencia; lanza 409 si no alcanza. */\n    public void aplicar(TipoMovimiento tipo, BigDecimal cantidadMov) {\n        BigDecimal c = MovimientoInventario.validarCantidad(tipo, cantidadMov);\n        switch (tipo) {\n            case ENTRADA -> cantidad = cantidad.add(c);\n            case SALIDA -> {\n                exigirDisponible(c);\n                cantidad = cantidad.subtract(c);\n            }\n            case RESERVA -> {\n                exigirDisponible(c);\n                reservado = reservado.add(c);\n            }\n            case AJUSTE -> {\n                BigDecimal nueva = cantidad.add(c);\n                if (nueva.signum() < 0 || nueva.compareTo(reservado) < 0) {\n                    throw new ConflictoException(\"El ajuste dejaría la existencia negativa o por debajo de lo reservado\");\n                }\n                cantidad = nueva;\n            }\n        }\n    }\n\n    /** Libera parte de lo reservado, por ejemplo al entregar el pedido que la reservó. */\n    public void liberarReserva(BigDecimal cantidadLiberada) {\n        BigDecimal c = MovimientoInventario.validarCantidad(TipoMovimiento.RESERVA, cantidadLiberada);\n        if (c.compareTo(reservado) > 0) {\n            throw new ConflictoException(\"No se puede liberar más de lo reservado: reservado \"\n                    + reservado.toPlainString() + \", solicitado \" + c.toPlainString());\n        }\n        reservado = reservado.subtract(c);\n    }\n\n    /** Devuelve lo disponible: existencia menos lo reservado. */\n    public BigDecimal disponible() {\n        return cantidad.subtract(reservado);\n    }\n\n    /** Rechaza la operación si la cantidad pedida supera lo disponible. */\n    private void exigirDisponible(BigDecimal c) {\n        if (c.compareTo(disponible()) > 0) {\n            throw new ConflictoException(\"Existencia insuficiente: disponible \" + disponible().toPlainString()\n                    + \", solicitado \" + c.toPlainString());\n        }\n    }\n\n    /** Devuelve el id del artículo. */\n    public UUID getArticuloId() { return articuloId; }\n    /** Devuelve el id del almacén. */\n    public UUID getAlmacenId() { return almacenId; }\n    /** Devuelve la cantidad total existente. */\n    public BigDecimal getCantidad() { return cantidad; }\n    /** Devuelve la cantidad reservada. */\n    public BigDecimal getReservado() { return reservado; }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/ExistenciaRepositorio.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto para guardar y consultar existencias, sin depender de JPA. */\npublic interface ExistenciaRepositorio {\n    Existencia guardar(Existencia existencia);\n    Optional<Existencia> buscar(UUID articuloId, UUID almacenId);\n    List<Existencia> buscarPorArticulo(UUID articuloId);\n\n    /** Suma de cantidad en todos los almacenes, por artículo. */\n    java.util.Map<UUID, java.math.BigDecimal> cantidadTotalPorArticulo();\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/MovimientoInventario.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport java.math.BigDecimal;\nimport java.math.RoundingMode;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Movimiento inmutable de inventario. Se compensa con otro movimiento; nunca se borra. */\npublic final class MovimientoInventario {\n\n    private final UUID id;\n    private final UUID articuloId;\n    private final UUID almacenId;\n    private final TipoMovimiento tipo;\n    private final BigDecimal cantidad;\n    private final String lote;\n    private final String referencia;\n    private final Instant creadoUtc;\n\n    /** Constructor privado: los movimientos se crean con sus fábricas. */\n    private MovimientoInventario(UUID id, UUID articuloId, UUID almacenId, TipoMovimiento tipo, BigDecimal cantidad,\n                                 String lote, String referencia, Instant creadoUtc) {\n        this.id = id;\n        this.articuloId = articuloId;\n        this.almacenId = almacenId;\n        this.tipo = tipo;\n        this.cantidad = cantidad;\n        this.lote = lote;\n        this.referencia = referencia;\n        this.creadoUtc = creadoUtc;\n    }\n\n    /** Crea un movimiento nuevo y valida su cantidad según el tipo. */\n    public static MovimientoInventario crear(UUID articuloId, UUID almacenId, TipoMovimiento tipo, BigDecimal cantidad,\n                                             String lote, String referencia, Instant creadoUtc) {\n        if (articuloId == null || almacenId == null) {\n            throw new ReglaDeNegocioException(\"El artículo y el almacén son obligatorios\");\n        }\n        if (tipo == null) {\n            throw new ReglaDeNegocioException(\"El tipo de movimiento es obligatorio\");\n        }\n        BigDecimal c = validarCantidad(tipo, cantidad);\n        String loteLimpio = lote == null || lote.isBlank() ? null : lote.trim();\n        String refLimpia = referencia == null || referencia.isBlank() ? null : referencia.trim();\n        return new MovimientoInventario(UUID.randomUUID(), articuloId, almacenId, tipo, c, loteLimpio, refLimpia, creadoUtc);\n    }\n\n    /** Reconstruye un movimiento desde la base de datos sin aplicar reglas. */\n    public static MovimientoInventario reconstruir(UUID id, UUID articuloId, UUID almacenId, TipoMovimiento tipo,\n                                                   BigDecimal cantidad, String lote, String referencia, Instant creadoUtc) {\n        return new MovimientoInventario(id, articuloId, almacenId, tipo, cantidad, lote, referencia, creadoUtc);\n    }\n\n    /** Cantidades con tres decimales. AJUSTE admite negativos; los demás tipos deben ser positivos. */\n    static BigDecimal validarCantidad(TipoMovimiento tipo, BigDecimal cantidad) {\n        if (cantidad == null) {\n            throw new ReglaDeNegocioException(\"La cantidad es obligatoria\");\n        }\n        BigDecimal c = cantidad.setScale(3, RoundingMode.HALF_EVEN);\n        if (tipo == TipoMovimiento.AJUSTE) {\n            if (c.signum() == 0) {\n                throw new ReglaDeNegocioException(\"El ajuste no puede ser cero\");\n            }\n        } else if (c.signum() <= 0) {\n            throw new ReglaDeNegocioException(\"La cantidad debe ser mayor a cero\");\n        }\n        return c;\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el id del artículo. */\n    public UUID getArticuloId() { return articuloId; }\n    /** Devuelve el id del almacén. */\n    public UUID getAlmacenId() { return almacenId; }\n    /** Devuelve el tipo de movimiento. */\n    public TipoMovimiento getTipo() { return tipo; }\n    /** Devuelve la cantidad. */\n    public BigDecimal getCantidad() { return cantidad; }\n    /** Devuelve el lote, si aplica. */\n    public String getLote() { return lote; }\n    /** Devuelve la referencia que explica el movimiento, por ejemplo el pedido o la orden. */\n    public String getReferencia() { return referencia; }\n    /** Devuelve el instante de creación en UTC. */\n    public Instant getCreadoUtc() { return creadoUtc; }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/MovimientoRepositorio.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport java.util.List;\n\n/** Puerto para guardar y consultar movimientos, sin depender de JPA. */\npublic interface MovimientoRepositorio {\n    MovimientoInventario guardar(MovimientoInventario movimiento);\n    List<MovimientoInventario> buscarPorLote(String lote);\n\n    /** Movimientos más recientes primero, hasta {@code limite}. */\n    List<MovimientoInventario> listarRecientesDeArticulo(java.util.UUID articuloId, int limite);\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/OrdenOperacion.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport java.math.BigDecimal;\nimport java.math.RoundingMode;\nimport java.util.UUID;\n\n/** Orden de producción o de servicio. Solo se cierra con cantidad real mayor a cero. */\npublic class OrdenOperacion {\n\n    private final UUID id;\n    private final TipoOrden tipo;\n    private EstatusOrden estatus;\n    private final BigDecimal cantidadObjetivo;\n    private BigDecimal cantidadReal;\n\n    /** Constructor privado: las órdenes se crean con sus fábricas. */\n    private OrdenOperacion(UUID id, TipoOrden tipo, EstatusOrden estatus, BigDecimal cantidadObjetivo,\n                           BigDecimal cantidadReal) {\n        this.id = id;\n        this.tipo = tipo;\n        this.estatus = estatus;\n        this.cantidadObjetivo = cantidadObjetivo;\n        this.cantidadReal = cantidadReal;\n    }\n\n    /** Crea una orden abierta. La cantidad objetivo debe ser mayor a cero. */\n    public static OrdenOperacion crear(TipoOrden tipo, BigDecimal cantidadObjetivo) {\n        if (tipo == null) {\n            throw new ReglaDeNegocioException(\"El tipo de orden es obligatorio\");\n        }\n        if (cantidadObjetivo == null || cantidadObjetivo.signum() <= 0) {\n            throw new ReglaDeNegocioException(\"La cantidad objetivo debe ser mayor a cero\");\n        }\n        return new OrdenOperacion(UUID.randomUUID(), tipo, EstatusOrden.ABIERTA,\n                cantidadObjetivo.setScale(3, RoundingMode.HALF_EVEN), null);\n    }\n\n    /** Reconstruye una orden desde la base de datos sin aplicar reglas. */\n    public static OrdenOperacion reconstruir(UUID id, TipoOrden tipo, EstatusOrden estatus, BigDecimal objetivo,\n                                             BigDecimal real) {\n        return new OrdenOperacion(id, tipo, estatus, objetivo, real);\n    }\n\n    /** Cierra la orden con la cantidad real. Una orden cerrada no se vuelve a cerrar; la cantidad real debe ser mayor a cero. */\n    public void cerrar(BigDecimal real) {\n        if (estatus == EstatusOrden.CERRADA) {\n            throw new ConflictoException(\"La orden ya está cerrada\");\n        }\n        if (real == null || real.signum() <= 0) {\n            throw new ReglaDeNegocioException(\"Cerrar una orden requiere la cantidad producida o el servicio completado\");\n        }\n        this.cantidadReal = real.setScale(3, RoundingMode.HALF_EVEN);\n        this.estatus = EstatusOrden.CERRADA;\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el tipo de orden. */\n    public TipoOrden getTipo() { return tipo; }\n    /** Devuelve el estatus. */\n    public EstatusOrden getEstatus() { return estatus; }\n    /** Devuelve la cantidad objetivo. */\n    public BigDecimal getCantidadObjetivo() { return cantidadObjetivo; }\n    /** Devuelve la cantidad real, o nula si la orden sigue abierta. */\n    public BigDecimal getCantidadReal() { return cantidadReal; }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/OrdenRepositorio.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto para guardar y consultar órdenes, sin depender de JPA. */\npublic interface OrdenRepositorio {\n    OrdenOperacion guardar(OrdenOperacion orden);\n    Optional<OrdenOperacion> buscarPorId(UUID id);\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/RecepcionesRepositorio.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport java.util.UUID;\n\n/** Control de recepciones de compras ya aplicadas. */\npublic interface RecepcionesRepositorio {\n\n    /** Registra la recepción como aplicada. Devuelve false si ya estaba aplicada. */\n    boolean marcarProcesada(UUID eventoId);\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/RecursoNoEncontradoException.java": "package com.mx.josesaid.develop.inventario.domain;\n\n/** El recurso no existe. HTTP 404. */\npublic class RecursoNoEncontradoException extends RuntimeException {\n    /** Se lanza cuando no existe el recurso pedido. */\n    public RecursoNoEncontradoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/ReglaDeNegocioException.java": "package com.mx.josesaid.develop.inventario.domain;\n\n/** Una operación viola una regla de negocio. HTTP 422. */\npublic class ReglaDeNegocioException extends RuntimeException {\n    /** Se lanza cuando una regla de negocio no se cumple. El mensaje se muestra al cliente. */\n    public ReglaDeNegocioException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/ReservasPedidoRepositorio.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport java.math.BigDecimal;\nimport java.util.List;\nimport java.util.UUID;\n\n/** Reservas creadas por los pedidos y control de eventos de pedidos ya aplicados. */\npublic interface ReservasPedidoRepositorio {\n\n    /** Registra el evento como aplicado. Devuelve false si ya estaba aplicado. */\n    boolean marcarProcesado(UUID pedidoId, String evento);\n\n    void guardarReserva(UUID pedidoId, UUID articuloId, UUID almacenId, BigDecimal cantidad);\n\n    List<Reserva> reservasDe(UUID pedidoId);\n\n    void eliminarReservas(UUID pedidoId);\n\n    /**\n     * Reserva registrada para un pedido: artículo, almacén y cantidad.\n     *\n     * @param articuloId componente de tipo {@code UUID}.\n     * @param almacenId componente de tipo {@code UUID}.\n     * @param cantidad componente de tipo {@code BigDecimal}.\n     */\n    record Reserva(UUID articuloId, UUID almacenId, BigDecimal cantidad) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/SolicitudInvalidaException.java": "package com.mx.josesaid.develop.inventario.domain;\n\n/** La solicitud no cumple requisitos de forma, como lote obligatorio ausente. HTTP 400. */\npublic class SolicitudInvalidaException extends RuntimeException {\n    /** Se lanza cuando la solicitud no es válida. */\n    public SolicitudInvalidaException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/TipoMovimiento.java": "package com.mx.josesaid.develop.inventario.domain;\n\n/** Tipos de movimiento: entrada, salida, ajuste y reserva. */\npublic enum TipoMovimiento { ENTRADA, SALIDA, AJUSTE, RESERVA }\n", "src/main/java/com/mx/josesaid/develop/inventario/domain/TipoOrden.java": "package com.mx.josesaid.develop.inventario.domain;\n\n/** Tipos de orden: producción o servicio. */\npublic enum TipoOrden { PRODUCCION, SERVICIO }\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/compras/ListenerRecepciones.java": "package com.mx.josesaid.develop.inventario.infrastructure.compras;\n\nimport com.mx.josesaid.develop.inventario.application.RecepcionesService;\nimport com.mx.josesaid.develop.inventario.application.RecepcionesService.LineaRecibida;\nimport java.math.BigDecimal;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.kafka.annotation.KafkaListener;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Aplica a inventario las recepciones de compras-proveedores-ms (evento insumos-recibidos).\n * Un mensaje mal formado o sin evento_id se registra y se descarta. Un fallo de base de datos se propaga para que Kafka reintente.\n */\n@Component\npublic class ListenerRecepciones {\n\n    private static final Logger log = LoggerFactory.getLogger(ListenerRecepciones.class);\n    static final String TIPO_RECIBIDOS = \"insumos-recibidos\";\n\n    private final RecepcionesService servicio;\n    private final ObjectMapper mapper;\n    private final String almacenConfigurado;\n\n    /** Recibe el servicio de recepciones, el lector JSON y la configuración del tópico de compras. */\n    public ListenerRecepciones(RecepcionesService servicio, ObjectMapper mapper,\n                               @Value(\"${inventario.pedidos.almacen-id:}\") String almacenConfigurado) {\n        this.servicio = servicio;\n        this.mapper = mapper;\n        this.almacenConfigurado = almacenConfigurado;\n    }\n\n    /** Recibe desde Kafka el evento de recepción de una orden de compra y lo registra como entrada de inventario. */\n    @KafkaListener(topics = \"${inventario.compras.topico:compras.eventos}\",\n                   groupId = \"inventario-operaciones-ms-compras\")\n    public void recibir(String mensaje) {\n        Sobre sobre;\n        try {\n            sobre = mapper.readValue(mensaje, Sobre.class);\n        } catch (RuntimeException e) {\n            log.warn(\"Evento de compras descartado: {}\", e.getClass().getSimpleName());\n            return;\n        }\n        if (!TIPO_RECIBIDOS.equals(sobre.tipo())) {\n            return;\n        }\n        UUID eventoId;\n        UUID ordenId;\n        List<LineaRecibida> lineas;\n        try {\n            Map<String, Object> datos = sobre.datos();\n            eventoId = UUID.fromString(String.valueOf(datos.get(\"evento_id\")));\n            ordenId = UUID.fromString(sobre.agregadoId());\n            lineas = aLineas(datos);\n        } catch (RuntimeException e) {\n            log.warn(\"Recepción descartada por datos inválidos: {}\", e.getClass().getSimpleName());\n            return;\n        }\n        if (almacenConfigurado == null || almacenConfigurado.isBlank()) {\n            log.error(\"Orden {}: falta inventario.pedidos.almacen-id; no se registra la recepción\", ordenId);\n            return;\n        }\n        servicio.registrar(eventoId, ordenId, UUID.fromString(almacenConfigurado), lineas);\n    }\n\n    /** Convierte las líneas del evento en líneas de recepción. */\n    private static List<LineaRecibida> aLineas(Map<String, Object> datos) {\n        if (!(datos.get(\"lineas\") instanceof List<?> lista)) {\n            throw new IllegalArgumentException(\"La recepción no trae líneas\");\n        }\n        return lista.stream()\n                .map(m -> (Map<?, ?>) m)\n                .map(m -> new LineaRecibida(String.valueOf(m.get(\"sku\")),\n                        new BigDecimal(String.valueOf(m.get(\"cantidad\")))))\n                .toList();\n    }\n\n    /**\n     * Sobre que publica compras-proveedores-ms por el outbox.\n     *\n     * @param tipo componente de tipo {@code String}.\n     * @param agregadoId componente de tipo {@code String}.\n     * @param datos componente de tipo {@code Map<String, Object>}.\n     */\n    public record Sobre(String tipo, String agregadoId, Map<String, Object> datos) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/compras/RecepcionesJdbc.java": "package com.mx.josesaid.develop.inventario.infrastructure.compras;\n\nimport com.mx.josesaid.develop.inventario.domain.RecepcionesRepositorio;\nimport java.sql.Timestamp;\nimport java.time.Clock;\nimport java.util.UUID;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Repository;\n\n/** Registro en base de datos de las recepciones ya aplicadas. */\n@Repository\nclass RecepcionesJdbc implements RecepcionesRepositorio {\n\n    private final JdbcTemplate jdbc;\n    private final Clock reloj;\n\n    RecepcionesJdbc(JdbcTemplate jdbc, Clock reloj) {\n        this.jdbc = jdbc;\n        this.reloj = reloj;\n    }\n\n    /** Marca el evento como procesado. Devuelve falso si ya estaba procesado, para no aplicarlo dos veces. */\n    @Override\n    public boolean marcarProcesada(UUID eventoId) {\n        return jdbc.update(\n                \"INSERT INTO recepciones_procesadas (evento_id, procesado_utc) VALUES (?, ?) ON CONFLICT DO NOTHING\",\n                eventoId, Timestamp.from(reloj.instant())) == 1;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/idempotencia/Idempotencia.java": "package com.mx.josesaid.develop.inventario.infrastructure.idempotencia;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.inventario.domain.ConflictoException;\nimport com.mx.josesaid.develop.inventario.domain.ReglaDeNegocioException;\nimport java.nio.charset.StandardCharsets;\nimport java.security.MessageDigest;\nimport java.security.NoSuchAlgorithmException;\nimport java.util.HexFormat;\nimport java.util.function.Supplier;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.stereotype.Component;\n\n/**\n * Hace seguras de reintentar las altas que reciben la cabecera Idempotency-Key.\n * Misma clave y misma petición: devuelve la respuesta original, sin crear nada nuevo.\n * Misma clave con otra petición: 422. Clave todavía en proceso: 409.\n * Sin cabecera: la operación se ejecuta como siempre.\n */\n@Component\npublic class Idempotencia {\n\n    public static final String CABECERA = \"Idempotency-Key\";\n\n    private final RegistroIdempotencia registro;\n    private final ObjectMapper mapper;\n\n    /** Recibe el registro de claves y el serializador JSON. */\n    public Idempotencia(RegistroIdempotencia registro, ObjectMapper mapper) {\n        this.registro = registro;\n        this.mapper = mapper;\n    }\n\n    /** Ejecuta una operación una sola vez por Idempotency-Key. Una misma clave con la misma petición devuelve la respuesta guardada; con otra petición, rechaza. Si la operación falla, libera la clave para reintentar. */\n    public <T> ResponseEntity<?> ejecutar(String clave, String ruta, Object peticion,\n                                          HttpStatus estado, Supplier<T> operacion) {\n        if (clave == null || clave.isBlank()) {\n            return ResponseEntity.status(estado).body(operacion.get());\n        }\n        String huella = huella(ruta, peticion);\n        if (!registro.reservar(clave, huella)) {\n            RegistroIdempotencia.Registro previo = registro.buscar(clave)\n                    .orElseThrow(() -> new ConflictoException(\"La Idempotency-Key ya no está disponible. Intente de nuevo.\"));\n            if (!previo.huella().equals(huella)) {\n                throw new ReglaDeNegocioException(\"La Idempotency-Key ya se usó con una petición distinta.\");\n            }\n            if (!previo.completada()) {\n                throw new ConflictoException(\"La petición con esta Idempotency-Key aún se está procesando.\");\n            }\n            return ResponseEntity.status(previo.estatus())\n                    .contentType(MediaType.APPLICATION_JSON)\n                    .body(previo.cuerpo());\n        }\n        T cuerpo;\n        try {\n            cuerpo = operacion.get();\n        } catch (RuntimeException e) {\n            registro.liberar(clave);\n            throw e;\n        }\n        registro.completar(clave, estado.value(), serializar(cuerpo));\n        return ResponseEntity.status(estado).body(cuerpo);\n    }\n\n    /** Calcula la huella SHA-256 de la ruta y el cuerpo de la petición, para detectar si una clave se reutiliza con otra petición. */\n    private String huella(String ruta, Object peticion) {\n        try {\n            byte[] digest = MessageDigest.getInstance(\"SHA-256\")\n                    .digest((ruta + \"\\n\" + mapper.writeValueAsString(peticion)).getBytes(StandardCharsets.UTF_8));\n            return HexFormat.of().formatHex(digest);\n        } catch (JsonProcessingException | NoSuchAlgorithmException e) {\n            throw new IllegalStateException(\"No se pudo calcular la huella de la petición\", e);\n        }\n    }\n\n    /** Convierte la respuesta en JSON para guardarla. */\n    private String serializar(Object cuerpo) {\n        try {\n            return mapper.writeValueAsString(cuerpo);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo guardar la respuesta idempotente\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/idempotencia/RegistroIdempotencia.java": "package com.mx.josesaid.develop.inventario.infrastructure.idempotencia;\n\nimport java.sql.Timestamp;\nimport java.time.Clock;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Optional;\nimport org.springframework.dao.DuplicateKeyException;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Repository;\n\n/**\n * Guarda el estado de cada clave Idempotency-Key. Una respuesta completada se conserva 24 horas.\n * Una reserva que nunca se completó (la petición murió a medio camino) se puede retomar tras\n * {@link #CONCESION_RESERVA}, para que la clave no quede bloqueada todo el día.\n */\n@Repository\nclass RegistroIdempotencia {\n\n    static final Duration VIGENCIA = Duration.ofHours(24);\n    static final Duration CONCESION_RESERVA = Duration.ofMinutes(2);\n\n    /**\n     * Fila guardada para una clave: huella, estatus HTTP, cuerpo de la respuesta y si ya terminó.\n     *\n     * @param huella componente de tipo {@code String}.\n     * @param estatus componente de tipo {@code int}.\n     * @param cuerpo componente de tipo {@code String}.\n     * @param completada componente de tipo {@code boolean}.\n     */\n    record Registro(String huella, int estatus, String cuerpo, boolean completada) {}\n\n    private final JdbcTemplate jdbc;\n    private final Clock reloj;\n\n    RegistroIdempotencia(JdbcTemplate jdbc, Clock reloj) {\n        this.jdbc = jdbc;\n        this.reloj = reloj;\n    }\n\n    /** Busca el registro de una clave que sigue vigente. */\n    Optional<Registro> buscar(String clave) {\n        return jdbc.query(\n                \"SELECT huella, estatus_http, cuerpo, completada FROM idempotencia WHERE clave = ? AND creado_utc > ?\",\n                (rs, n) -> new Registro(rs.getString(1), rs.getInt(2), rs.getString(3), rs.getBoolean(4)),\n                clave, enTiempo(vencimiento())).stream().findFirst();\n    }\n\n    /**\n     * Reserva la clave. Devuelve false si otra petición la tiene en curso o ya terminó.\n     * Si la reserva existente nunca se completó y su concesión venció, la retoma.\n     */\n    boolean reservar(String clave, String huella) {\n        jdbc.update(\"DELETE FROM idempotencia WHERE creado_utc <= ?\", enTiempo(vencimiento()));\n        try {\n            jdbc.update(\"INSERT INTO idempotencia (clave, huella, estatus_http, cuerpo, completada, creado_utc) VALUES (?, ?, 0, NULL, FALSE, ?)\",\n                    clave, huella, enTiempo(reloj.instant()));\n            return true;\n        } catch (DuplicateKeyException e) {\n            return retomarReservaVencida(clave, huella);\n        }\n    }\n\n    /** Solo una petición gana la retoma: el UPDATE es condicional, así que es atómico. */\n    private boolean retomarReservaVencida(String clave, String huella) {\n        Instant ahora = reloj.instant();\n        int filas = jdbc.update(\n                \"UPDATE idempotencia SET huella = ?, creado_utc = ? WHERE clave = ? AND completada = FALSE AND creado_utc <= ?\",\n                huella, enTiempo(ahora), clave, enTiempo(ahora.minus(CONCESION_RESERVA)));\n        return filas == 1;\n    }\n\n    /** Guarda la respuesta de una operación terminada. */\n    void completar(String clave, int estatus, String cuerpo) {\n        jdbc.update(\"UPDATE idempotencia SET estatus_http = ?, cuerpo = ?, completada = TRUE WHERE clave = ?\",\n                estatus, cuerpo, clave);\n    }\n\n    /** Libera la reserva cuando la operación falló, para que el cliente pueda reintentar. */\n    void liberar(String clave) {\n        jdbc.update(\"DELETE FROM idempotencia WHERE clave = ? AND completada = FALSE\", clave);\n    }\n\n    /** Calcula el límite de vigencia de las claves. */\n    private Instant vencimiento() {\n        return reloj.instant().minus(VIGENCIA);\n    }\n\n    /** Convierte un instante a Timestamp para la base de datos. */\n    private static Timestamp enTiempo(Instant instante) {\n        return Timestamp.from(instante);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/indicadores/PublicadorIndicadoresMovimientos.java": "package com.mx.josesaid.develop.inventario.infrastructure.indicadores;\n\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.concurrent.TimeUnit;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Publica a reportes-ejecutivos-ms el indicador \"movimientos del mes\" del área de operaciones.\n *\n * <p>Cuenta los movimientos de inventario del mes, por hora de la Ciudad de México. Se recalculan el mes\n * actual y el anterior en cada ciclo. Es una foto del periodo, no un evento: no pasa por el outbox; si un\n * envío falla, el siguiente ciclo lo corrige.\n */\n@Component\npublic class PublicadorIndicadoresMovimientos {\n\n    private static final Logger log = LoggerFactory.getLogger(PublicadorIndicadoresMovimientos.class);\n\n    /** Valor del enum Area de reportes-ejecutivos-ms. */\n    public static final String AREA = \"OPERACIONES\";\n    public static final String NOMBRE = \"movimientos_mes\";\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    private static final String SQL_MOVIMIENTOS = \"\"\"\n            SELECT COUNT(*)::numeric\n            FROM movimientos_inventario\n            WHERE TO_CHAR(creado_utc AT TIME ZONE 'America/Mexico_City', 'YYYY-MM') = ?\n            \"\"\";\n\n    private final JdbcTemplate jdbc;\n    private final KafkaTemplate<String, String> kafka;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n    private final String topico;\n\n    /** Recibe JDBC para contar, Kafka para publicar, el serializador, el reloj y el tópico. */\n    public PublicadorIndicadoresMovimientos(JdbcTemplate jdbc, KafkaTemplate<String, String> kafka,\n                                            ObjectMapper mapper, Clock reloj,\n                                            @Value(\"${indicadores.topico:indicadores-areas}\") String topico) {\n        this.jdbc = jdbc;\n        this.kafka = kafka;\n        this.mapper = mapper;\n        this.reloj = reloj;\n        this.topico = topico;\n    }\n\n    /** Publica el indicador de movimientos del mes actual y del anterior. */\n    @Scheduled(fixedDelayString = \"${indicadores.intervalo-ms:3600000}\",\n            initialDelayString = \"${indicadores.inicio-ms:30000}\")\n    public void publicar() {\n        YearMonth actual = YearMonth.now(reloj.withZone(ZONA));\n        publicarPeriodo(actual.minusMonths(1).toString());\n        publicarPeriodo(actual.toString());\n    }\n\n    /** Calcula y envía el indicador de un mes (\"AAAA-MM\"). Un fallo se registra y se reintenta en el siguiente ciclo. */\n    public void publicarPeriodo(String periodo) {\n        BigDecimal valor = jdbc.queryForObject(SQL_MOVIMIENTOS, BigDecimal.class, periodo);\n        String payload = mapper.writeValueAsString(\n                new IndicadorEvento(AREA, NOMBRE, periodo, valor, Instant.now(reloj)));\n        try {\n            kafka.send(topico, AREA + \"|\" + NOMBRE + \"|\" + periodo, payload).get(10, TimeUnit.SECONDS);\n            log.info(\"Indicador publicado: {} {} {}\", AREA, NOMBRE, periodo);\n        } catch (InterruptedException ie) {\n            Thread.currentThread().interrupt();\n        } catch (Exception ex) {\n            log.warn(\"No se pudo publicar el indicador {} {}: {}\", NOMBRE, periodo, ex.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Formato que espera reportes-ejecutivos-ms (ListenerIndicadores.IndicadorEvento).\n     *\n     * @param area componente de tipo {@code String}.\n     * @param nombre componente de tipo {@code String}.\n     * @param periodo componente de tipo {@code String}.\n     * @param valor componente de tipo {@code BigDecimal}.\n     * @param fuenteActualizadaUtc componente de tipo {@code Instant}.\n     */\n    public record IndicadorEvento(String area, String nombre, String periodo, BigDecimal valor,\n                                  Instant fuenteActualizadaUtc) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/outbox/OutboxEntity.java": "package com.mx.josesaid.develop.inventario.infrastructure.outbox;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Evento pendiente de publicar a Kafka. Se escribe en la misma transacción que el cambio de negocio. */\n@Entity\n@Table(name = \"outbox_eventos\")\npublic class OutboxEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(nullable = false, length = 100)\n    private String tipo;\n\n    @Column(name = \"agregado_id\", nullable = false, length = 100)\n    private String agregadoId;\n\n    /** Sobre JSON completo: tipo, agregadoId y datos. */\n    @Column(nullable = false, columnDefinition = \"TEXT\")\n    private String payload;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    @Column(name = \"publicado_utc\")\n    private Instant publicadoUtc;\n\n    @Column(nullable = false)\n    private int intentos;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected OutboxEntity() {\n        // requerido por JPA\n    }\n\n    /** Crea un evento pendiente de publicar en el outbox. */\n    public OutboxEntity(UUID id, String tipo, String agregadoId, String payload, Instant creadoUtc) {\n        this.id = id;\n        this.tipo = tipo;\n        this.agregadoId = agregadoId;\n        this.payload = payload;\n        this.creadoUtc = creadoUtc;\n        this.intentos = 0;\n    }\n\n    /** Marca el evento como publicado en la fecha indicada. */\n    public void marcarPublicado(Instant ahora) {\n        this.publicadoUtc = ahora;\n    }\n\n    /** Suma un intento fallido de publicación. */\n    public void registrarIntentoFallido() {\n        this.intentos++;\n    }\n\n    /** Devuelve el identificador del evento. */\n    public UUID getId() { return id; }\n    /** Devuelve el tipo del evento. */\n    public String getTipo() { return tipo; }\n    /** Devuelve el id del agregado al que pertenece el evento. */\n    public String getAgregadoId() { return agregadoId; }\n    /** Devuelve el contenido JSON del evento. */\n    public String getPayload() { return payload; }\n    /** Devuelve la fecha de creación en UTC. */\n    public Instant getCreadoUtc() { return creadoUtc; }\n    /** Devuelve la fecha de publicación en UTC, o nula si no se ha publicado. */\n    public Instant getPublicadoUtc() { return publicadoUtc; }\n    /** Devuelve el número de intentos fallidos. */\n    public int getIntentos() { return intentos; }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/outbox/OutboxJpaRepository.java": "package com.mx.josesaid.develop.inventario.infrastructure.outbox;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla del outbox con Spring Data JPA. */\npublic interface OutboxJpaRepository extends JpaRepository<OutboxEntity, UUID> {\n\n    /** Eventos pendientes, del más antiguo al más nuevo, en lotes de 100. */\n    List<OutboxEntity> findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc();\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/outbox/PublicadorEventosOutbox.java": "package com.mx.josesaid.develop.inventario.infrastructure.outbox;\n\nimport com.mx.josesaid.develop.inventario.application.EventoDominio;\nimport com.mx.josesaid.develop.inventario.application.PublicadorEventos;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Implementación del patrón outbox: guarda el evento en la base de datos dentro de la\n * transacción de negocio. El envío a Kafka lo hace {@link RetransmisorOutbox}.\n */\n@Component\npublic class PublicadorEventosOutbox implements PublicadorEventos {\n\n    private final OutboxJpaRepository outbox;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el serializador JSON y el reloj. */\n    public PublicadorEventosOutbox(OutboxJpaRepository outbox, ObjectMapper mapper, Clock reloj) {\n        this.outbox = outbox;\n        this.mapper = mapper;\n        this.reloj = reloj;\n    }\n\n    /** Guarda el evento en el outbox dentro de la misma transacción que el cambio de datos. */\n    @Override\n    public void publicar(EventoDominio evento) {\n        String sobre = mapper.writeValueAsString(Map.of(\n                \"tipo\", evento.tipo(),\n                \"agregadoId\", evento.agregadoId(),\n                \"datos\", evento.datos()));\n        outbox.save(new OutboxEntity(UUID.randomUUID(), evento.tipo(), evento.agregadoId(),\n                sobre, Instant.now(reloj)));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/outbox/RetransmisorOutbox.java": "package com.mx.josesaid.develop.inventario.infrastructure.outbox;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.concurrent.TimeUnit;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Envía a Kafka los eventos pendientes del outbox.\n *\n * <p>Se detiene en el primer fallo para conservar el orden de los eventos.\n * Un evento con error queda pendiente y se reintenta en el siguiente ciclo.\n */\n@Component\npublic class RetransmisorOutbox {\n\n    /** Tópico donde se publican los eventos de identidad. */\n    public static final String TOPICO = \"inventario.eventos\";\n\n    private final OutboxJpaRepository outbox;\n    private final KafkaTemplate<String, String> kafka;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el productor de Kafka y el reloj. */\n    public RetransmisorOutbox(OutboxJpaRepository outbox, KafkaTemplate<String, String> kafka, Clock reloj) {\n        this.outbox = outbox;\n        this.kafka = kafka;\n        this.reloj = reloj;\n    }\n\n    /** Envía a Kafka los eventos pendientes. Si el envío falla, el evento queda para el siguiente intento. */\n    @Scheduled(fixedDelayString = \"${inventario.outbox.intervalo-ms:5000}\")\n    @Transactional\n    public void transmitir() {\n        for (OutboxEntity evento : outbox.findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc()) {\n            try {\n                kafka.send(TOPICO, evento.getAgregadoId(), evento.getPayload()).get(10, TimeUnit.SECONDS);\n                evento.marcarPublicado(Instant.now(reloj));\n            } catch (InterruptedException ie) {\n                Thread.currentThread().interrupt();\n                return;\n            } catch (Exception ex) {\n                evento.registrarIntentoFallido();\n                return;\n            }\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/pedidos/ListenerPedidos.java": "package com.mx.josesaid.develop.inventario.infrastructure.pedidos;\n\nimport com.mx.josesaid.develop.inventario.application.ReservasPedidoService;\nimport com.mx.josesaid.develop.inventario.application.ReservasPedidoService.LineaPedido;\nimport java.math.BigDecimal;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.kafka.annotation.KafkaListener;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Aplica a inventario los eventos de pedidos-ventas-ms: reserva al confirmar y descuenta al entregar.\n * Un mensaje mal formado se registra y se descarta. Un fallo de base de datos se propaga para que Kafka reintente.\n */\n@Component\npublic class ListenerPedidos {\n\n    private static final Logger log = LoggerFactory.getLogger(ListenerPedidos.class);\n\n    private final ReservasPedidoService servicio;\n    private final ObjectMapper mapper;\n    private final String almacenConfigurado;\n\n    /** Recibe el servicio de reservas, el lector JSON y la configuración del tópico de pedidos. */\n    public ListenerPedidos(ReservasPedidoService servicio, ObjectMapper mapper,\n                           @Value(\"${inventario.pedidos.almacen-id:}\") String almacenConfigurado) {\n        this.servicio = servicio;\n        this.mapper = mapper;\n        this.almacenConfigurado = almacenConfigurado;\n    }\n\n    /** Recibe desde Kafka los eventos de pedidos: confirmado reserva existencias y entregado las descuenta. */\n    @KafkaListener(topics = \"${inventario.pedidos.topico:pedidos.eventos}\",\n                   groupId = \"inventario-operaciones-ms-pedidos\")\n    public void recibir(String mensaje) {\n        Sobre sobre;\n        try {\n            sobre = mapper.readValue(mensaje, Sobre.class);\n        } catch (RuntimeException e) {\n            log.warn(\"Evento de pedidos descartado: {}\", e.getClass().getSimpleName());\n            return;\n        }\n        String tipo = sobre.tipo();\n        if (!ReservasPedidoService.EVENTO_CONFIRMADO.equals(tipo) && !ReservasPedidoService.EVENTO_ENTREGADO.equals(tipo)) {\n            return;\n        }\n        UUID pedidoId;\n        try {\n            pedidoId = UUID.fromString(sobre.agregadoId());\n        } catch (RuntimeException e) {\n            log.warn(\"Evento {} descartado por identificador inválido\", tipo);\n            return;\n        }\n        if (ReservasPedidoService.EVENTO_ENTREGADO.equals(tipo)) {\n            servicio.entregar(pedidoId);\n            return;\n        }\n        List<LineaPedido> lineas;\n        try {\n            lineas = aLineas(sobre.datos());\n        } catch (RuntimeException e) {\n            log.warn(\"Evento {} descartado por datos inválidos: {}\", tipo, e.getClass().getSimpleName());\n            return;\n        }\n        if (almacenConfigurado == null || almacenConfigurado.isBlank()) {\n            log.error(\"Pedido {}: falta inventario.pedidos.almacen-id; no se reserva\", pedidoId);\n            return;\n        }\n        servicio.reservar(pedidoId, UUID.fromString(almacenConfigurado), lineas);\n    }\n\n    /** Convierte las líneas del evento en líneas de pedido. */\n    private static List<LineaPedido> aLineas(Map<String, Object> datos) {\n        Object crudas = datos == null ? null : datos.get(\"lineas\");\n        if (!(crudas instanceof List<?> lista)) {\n            throw new IllegalArgumentException(\"El evento no trae líneas\");\n        }\n        return lista.stream()\n                .map(m -> (Map<?, ?>) m)\n                .map(m -> new LineaPedido(UUID.fromString(String.valueOf(m.get(\"productoId\"))),\n                        new BigDecimal(String.valueOf(m.get(\"cantidad\")))))\n                .toList();\n    }\n\n    /**\n     * Sobre que publica pedidos-ventas-ms por el outbox.\n     *\n     * @param tipo componente de tipo {@code String}.\n     * @param agregadoId componente de tipo {@code String}.\n     * @param datos componente de tipo {@code Map<String, Object>}.\n     */\n    public record Sobre(String tipo, String agregadoId, Map<String, Object> datos) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/pedidos/ReservasPedidoJdbc.java": "package com.mx.josesaid.develop.inventario.infrastructure.pedidos;\n\nimport com.mx.josesaid.develop.inventario.domain.ReservasPedidoRepositorio;\nimport java.math.BigDecimal;\nimport java.sql.Timestamp;\nimport java.time.Clock;\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Repository;\n\n/** Registro en base de datos de los pedidos procesados y sus reservas. */\n@Repository\nclass ReservasPedidoJdbc implements ReservasPedidoRepositorio {\n\n    private final JdbcTemplate jdbc;\n    private final Clock reloj;\n\n    ReservasPedidoJdbc(JdbcTemplate jdbc, Clock reloj) {\n        this.jdbc = jdbc;\n        this.reloj = reloj;\n    }\n\n    /** Marca el evento del pedido como procesado. Devuelve falso si ya estaba procesado. */\n    @Override\n    public boolean marcarProcesado(UUID pedidoId, String evento) {\n        return jdbc.update(\n                \"INSERT INTO pedidos_procesados (pedido_id, evento, procesado_utc) VALUES (?, ?, ?) ON CONFLICT DO NOTHING\",\n                pedidoId, evento, Timestamp.from(reloj.instant())) == 1;\n    }\n\n    /** Guarda la reserva de un artículo para un pedido. */\n    @Override\n    public void guardarReserva(UUID pedidoId, UUID articuloId, UUID almacenId, BigDecimal cantidad) {\n        jdbc.update(\"INSERT INTO reservas_pedido (pedido_id, articulo_id, almacen_id, cantidad) VALUES (?, ?, ?, ?)\",\n                pedidoId, articuloId, almacenId, cantidad);\n    }\n\n    /** Devuelve las reservas de un pedido. */\n    @Override\n    public List<Reserva> reservasDe(UUID pedidoId) {\n        return jdbc.query(\n                \"SELECT articulo_id, almacen_id, cantidad FROM reservas_pedido WHERE pedido_id = ? ORDER BY id\",\n                (rs, n) -> new Reserva(rs.getObject(1, UUID.class), rs.getObject(2, UUID.class), rs.getBigDecimal(3)),\n                pedidoId);\n    }\n\n    /** Elimina las reservas de un pedido ya entregado. */\n    @Override\n    public void eliminarReservas(UUID pedidoId) {\n        jdbc.update(\"DELETE FROM reservas_pedido WHERE pedido_id = ?\", pedidoId);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/AlmacenEntity.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.util.UUID;\n\n/** Fila de la tabla de almacenes. */\n@Entity\n@Table(name = \"almacenes\")\nclass AlmacenEntity {\n    @Id UUID id;\n    @Column(nullable = false, length = 100) String nombre;\n    @Column(nullable = false, length = 200) String ubicacion;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected AlmacenEntity() {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/AlmacenJpaRepository.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de almacenes con Spring Data JPA. */\ninterface AlmacenJpaRepository extends JpaRepository<AlmacenEntity, UUID> {\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/AlmacenRepositorioJpa.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.inventario.domain.Almacen;\nimport com.mx.josesaid.develop.inventario.domain.AlmacenRepositorio;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\n\n/** Implementa el puerto de almacenes con JPA. */\n@Component\nclass AlmacenRepositorioJpa implements AlmacenRepositorio {\n\n    private final AlmacenJpaRepository jpa;\n\n    AlmacenRepositorioJpa(AlmacenJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda un almacén y devuelve el guardado. */\n    @Override\n    public Almacen guardar(Almacen a) {\n        AlmacenEntity e = new AlmacenEntity();\n        e.id = a.getId();\n        e.nombre = a.getNombre();\n        e.ubicacion = a.getUbicacion();\n        jpa.save(e);\n        return a;\n    }\n\n    /** Busca un almacén por id. */\n    @Override\n    public Optional<Almacen> buscarPorId(UUID id) {\n        return jpa.findById(id).map(e -> Almacen.reconstruir(e.id, e.nombre, e.ubicacion));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/ArticuloEntity.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.math.BigDecimal;\nimport java.util.UUID;\n\n/** Fila de la tabla de artículos. */\n@Entity\n@Table(name = \"articulos\")\nclass ArticuloEntity {\n    @Id UUID id;\n    @Column(nullable = false, unique = true, length = 40) String sku;\n    @Column(nullable = false, length = 150) String nombre;\n    @Column(nullable = false, length = 10) String unidad;\n    @Column(name = \"lote_obligatorio\", nullable = false) boolean loteObligatorio;\n    @Column(nullable = false, precision = 14, scale = 3) BigDecimal minimo;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected ArticuloEntity() {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/ArticuloJpaRepository.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de artículos con Spring Data JPA. */\ninterface ArticuloJpaRepository extends JpaRepository<ArticuloEntity, UUID> {\n    boolean existsBySku(String sku);\n    java.util.Optional<ArticuloEntity> findBySku(String sku);\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/ArticuloRepositorioJpa.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.inventario.domain.Articulo;\nimport com.mx.josesaid.develop.inventario.domain.ArticuloRepositorio;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\n\n/** Implementa el puerto de artículos con JPA. */\n@Component\nclass ArticuloRepositorioJpa implements ArticuloRepositorio {\n\n    private final ArticuloJpaRepository jpa;\n\n    ArticuloRepositorioJpa(ArticuloJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda un artículo y devuelve el guardado. */\n    @Override\n    public Articulo guardar(Articulo a) {\n        ArticuloEntity e = new ArticuloEntity();\n        e.id = a.getId();\n        e.sku = a.getSku();\n        e.nombre = a.getNombre();\n        e.unidad = a.getUnidad();\n        e.loteObligatorio = a.isLoteObligatorio();\n        e.minimo = a.getMinimo();\n        jpa.save(e);\n        return a;\n    }\n\n    /** Busca un artículo por id. */\n    @Override\n    public Optional<Articulo> buscarPorId(UUID id) {\n        return jpa.findById(id).map(e -> Articulo.reconstruir(e.id, e.sku, e.nombre, e.unidad, e.loteObligatorio, e.minimo));\n    }\n\n    /** Lista los artículos cuya existencia total está por debajo de su mínimo. */\n    @Override\n    public java.util.List<Articulo> listarConMinimo() {\n        return jpa.findAll().stream()\n                .filter(e -> e.minimo.signum() > 0)\n                .map(e -> Articulo.reconstruir(e.id, e.sku, e.nombre, e.unidad, e.loteObligatorio, e.minimo))\n                .toList();\n    }\n\n    /** Indica si ya existe un artículo con ese SKU. */\n    @Override\n    public boolean existePorSku(String sku) {\n        return jpa.existsBySku(sku);\n    }\n\n    /** Busca un artículo por SKU. */\n    @Override\n    public Optional<Articulo> buscarPorSku(String sku) {\n        return jpa.findBySku(sku).map(e -> Articulo.reconstruir(e.id, e.sku, e.nombre, e.unidad, e.loteObligatorio, e.minimo));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/ExistenciaEntity.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.math.BigDecimal;\nimport java.util.UUID;\n\n/** Fila de la tabla de existencias: artículo, almacén, cantidad y reservado. */\n@Entity\n@Table(name = \"existencias\")\nclass ExistenciaEntity {\n    @Id UUID id;\n    @Column(name = \"articulo_id\", nullable = false) UUID articuloId;\n    @Column(name = \"almacen_id\", nullable = false) UUID almacenId;\n    @Column(nullable = false, precision = 14, scale = 3) BigDecimal cantidad;\n    @Column(nullable = false, precision = 14, scale = 3) BigDecimal reservado;\n    @Version Long version;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected ExistenciaEntity() {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/ExistenciaJpaRepository.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de existencias con Spring Data JPA. */\ninterface ExistenciaJpaRepository extends JpaRepository<ExistenciaEntity, UUID> {\n    Optional<ExistenciaEntity> findByArticuloIdAndAlmacenId(UUID articuloId, UUID almacenId);\n    List<ExistenciaEntity> findByArticuloId(UUID articuloId);\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/ExistenciaRepositorioJpa.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.inventario.domain.Existencia;\nimport com.mx.josesaid.develop.inventario.domain.ExistenciaRepositorio;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\n\n/** Implementa el puerto de existencias con JPA. */\n@Component\nclass ExistenciaRepositorioJpa implements ExistenciaRepositorio {\n\n    private final ExistenciaJpaRepository jpa;\n\n    ExistenciaRepositorioJpa(ExistenciaJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Actualiza la fila existente (con control de versión) o crea la del par artículo-almacén. */\n    @Override\n    public Existencia guardar(Existencia x) {\n        ExistenciaEntity e = jpa.findByArticuloIdAndAlmacenId(x.getArticuloId(), x.getAlmacenId())\n                .orElseGet(() -> {\n                    ExistenciaEntity nueva = new ExistenciaEntity();\n                    nueva.id = UUID.randomUUID();\n                    nueva.articuloId = x.getArticuloId();\n                    nueva.almacenId = x.getAlmacenId();\n                    return nueva;\n                });\n        e.cantidad = x.getCantidad();\n        e.reservado = x.getReservado();\n        jpa.save(e);\n        return x;\n    }\n\n    /** Busca la existencia de un artículo en un almacén. */\n    @Override\n    public Optional<Existencia> buscar(UUID articuloId, UUID almacenId) {\n        return jpa.findByArticuloIdAndAlmacenId(articuloId, almacenId).map(this::aDominio);\n    }\n\n    /** Devuelve las existencias de un artículo en todos sus almacenes. */\n    @Override\n    public List<Existencia> buscarPorArticulo(UUID articuloId) {\n        return jpa.findByArticuloId(articuloId).stream().map(this::aDominio).toList();\n    }\n\n    /** Devuelve la cantidad total por artículo, sumando todos los almacenes. */\n    @Override\n    public java.util.Map<UUID, java.math.BigDecimal> cantidadTotalPorArticulo() {\n        return jpa.findAll().stream().collect(java.util.stream.Collectors.groupingBy(\n                e -> e.articuloId,\n                java.util.stream.Collectors.reducing(java.math.BigDecimal.ZERO, e -> e.cantidad,\n                        java.math.BigDecimal::add)));\n    }\n\n    /** Convierte la fila en la existencia del dominio. */\n    private Existencia aDominio(ExistenciaEntity e) {\n        return Existencia.reconstruir(e.articuloId, e.almacenId, e.cantidad, e.reservado);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/MovimientoInventarioEntity.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.inventario.domain.TipoMovimiento;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Fila de la tabla de movimientos de inventario. */\n@Entity\n@Table(name = \"movimientos_inventario\")\nclass MovimientoInventarioEntity {\n    @Id UUID id;\n    @Column(name = \"articulo_id\", nullable = false) UUID articuloId;\n    @Column(name = \"almacen_id\", nullable = false) UUID almacenId;\n    @Enumerated(EnumType.STRING) @Column(nullable = false, length = 10) TipoMovimiento tipo;\n    @Column(nullable = false, precision = 14, scale = 3) BigDecimal cantidad;\n    @Column(length = 60) String lote;\n    @Column(length = 100) String referencia;\n    @Column(name = \"creado_utc\", nullable = false) Instant creadoUtc;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected MovimientoInventarioEntity() {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/MovimientoJpaRepository.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de movimientos con Spring Data JPA. */\ninterface MovimientoJpaRepository extends JpaRepository<MovimientoInventarioEntity, UUID> {\n    List<MovimientoInventarioEntity> findByLoteOrderByCreadoUtcAsc(String lote);\n\n    /** Devuelve los movimientos de un artículo, del más reciente al más antiguo, con límite. */\n    List<MovimientoInventarioEntity> findByArticuloIdOrderByCreadoUtcDesc(UUID articuloId,\n                                                                          org.springframework.data.domain.Pageable pageable);\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/MovimientoRepositorioJpa.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.inventario.domain.MovimientoInventario;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoRepositorio;\nimport java.util.List;\nimport org.springframework.stereotype.Component;\n\n/** Implementa el puerto de movimientos con JPA. */\n@Component\nclass MovimientoRepositorioJpa implements MovimientoRepositorio {\n\n    private final MovimientoJpaRepository jpa;\n\n    MovimientoRepositorioJpa(MovimientoJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda un movimiento y devuelve el guardado. */\n    @Override\n    public MovimientoInventario guardar(MovimientoInventario m) {\n        MovimientoInventarioEntity e = new MovimientoInventarioEntity();\n        e.id = m.getId();\n        e.articuloId = m.getArticuloId();\n        e.almacenId = m.getAlmacenId();\n        e.tipo = m.getTipo();\n        e.cantidad = m.getCantidad();\n        e.lote = m.getLote();\n        e.referencia = m.getReferencia();\n        e.creadoUtc = m.getCreadoUtc();\n        jpa.save(e);\n        return m;\n    }\n\n    /** Devuelve los movimientos recientes de un artículo, con límite. */\n    @Override\n    public List<MovimientoInventario> listarRecientesDeArticulo(java.util.UUID articuloId, int limite) {\n        return jpa.findByArticuloIdOrderByCreadoUtcDesc(articuloId,\n                        org.springframework.data.domain.PageRequest.of(0, limite)).stream()\n                .map(e -> MovimientoInventario.reconstruir(e.id, e.articuloId, e.almacenId, e.tipo, e.cantidad,\n                        e.lote, e.referencia, e.creadoUtc))\n                .toList();\n    }\n\n    /** Devuelve los movimientos de un lote. */\n    @Override\n    public List<MovimientoInventario> buscarPorLote(String lote) {\n        return jpa.findByLoteOrderByCreadoUtcAsc(lote).stream()\n                .map(e -> MovimientoInventario.reconstruir(e.id, e.articuloId, e.almacenId, e.tipo, e.cantidad,\n                        e.lote, e.referencia, e.creadoUtc))\n                .toList();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/OrdenEntity.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.inventario.domain.EstatusOrden;\nimport com.mx.josesaid.develop.inventario.domain.TipoOrden;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.math.BigDecimal;\nimport java.util.UUID;\n\n/** Fila de la tabla de órdenes de operación. */\n@Entity\n@Table(name = \"ordenes_operacion\")\nclass OrdenEntity {\n    @Id UUID id;\n    @Enumerated(EnumType.STRING) @Column(nullable = false, length = 12) TipoOrden tipo;\n    @Enumerated(EnumType.STRING) @Column(nullable = false, length = 10) EstatusOrden estatus;\n    @Column(name = \"cantidad_objetivo\", nullable = false, precision = 14, scale = 3) BigDecimal cantidadObjetivo;\n    @Column(name = \"cantidad_real\", precision = 14, scale = 3) BigDecimal cantidadReal;\n    @Version Long version;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected OrdenEntity() {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/OrdenJpaRepository.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de órdenes con Spring Data JPA. */\ninterface OrdenJpaRepository extends JpaRepository<OrdenEntity, UUID> {\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/infrastructure/persistence/OrdenRepositorioJpa.java": "package com.mx.josesaid.develop.inventario.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.inventario.domain.OrdenOperacion;\nimport com.mx.josesaid.develop.inventario.domain.OrdenRepositorio;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\n\n/** Implementa el puerto de órdenes con JPA. */\n@Component\nclass OrdenRepositorioJpa implements OrdenRepositorio {\n\n    private final OrdenJpaRepository jpa;\n\n    OrdenRepositorioJpa(OrdenJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda una orden y devuelve la guardada. */\n    @Override\n    public OrdenOperacion guardar(OrdenOperacion o) {\n        OrdenEntity e = jpa.findById(o.getId()).orElseGet(() -> {\n            OrdenEntity nueva = new OrdenEntity();\n            nueva.id = o.getId();\n            nueva.tipo = o.getTipo();\n            nueva.cantidadObjetivo = o.getCantidadObjetivo();\n            return nueva;\n        });\n        e.estatus = o.getEstatus();\n        e.cantidadReal = o.getCantidadReal();\n        jpa.save(e);\n        return o;\n    }\n\n    /** Busca una orden por id. */\n    @Override\n    public Optional<OrdenOperacion> buscarPorId(UUID id) {\n        return jpa.findById(id).map(e -> OrdenOperacion.reconstruir(e.id, e.tipo, e.estatus,\n                e.cantidadObjetivo, e.cantidadReal));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/seguridad/EntradaNoAutorizada.java": "package com.mx.josesaid.develop.inventario.seguridad;\n\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport java.io.IOException;\nimport org.springframework.security.core.AuthenticationException;\nimport org.springframework.security.oauth2.jwt.JwtValidationException;\nimport org.springframework.security.web.AuthenticationEntryPoint;\n\n/**\n * Responde 401 y deja el motivo en WWW-Authenticate. Solo expone el motivo de sesión cerrada;\n * cualquier otro fallo de validación se reporta como \"Invalid token\", sin detalles de decodificación.\n * Spring puede llamar dos veces al punto de entrada en la misma petición: el primer motivo se conserva.\n */\npublic class EntradaNoAutorizada implements AuthenticationEntryPoint {\n\n    private static final String MOTIVO_GENERICO = \"Invalid token\";\n    private static final String ATRIBUTO = EntradaNoAutorizada.class.getName() + \".motivo\";\n\n    /** Responde 401 cuando la petición no trae un token válido o el token fue rechazado. */\n    @Override\n    public void commence(HttpServletRequest request, HttpServletResponse response, AuthenticationException ex)\n            throws IOException {\n        String previo = (String) request.getAttribute(ATRIBUTO);\n        String motivo = previo != null ? previo : motivo(ex);\n        request.setAttribute(ATRIBUTO, motivo);\n        response.setHeader(\"WWW-Authenticate\",\n                \"Bearer error=\\\"invalid_token\\\", error_description=\\\"\" + motivo + \"\\\"\");\n        response.sendError(HttpServletResponse.SC_UNAUTHORIZED);\n    }\n\n    /** Explica por qué se rechazó el token, en texto breve para el log. */\n    private static String motivo(Throwable ex) {\n        for (Throwable t = ex; t != null; t = t.getCause()) {\n            if (t instanceof JwtValidationException jve && jve.getErrors().stream()\n                    .anyMatch(e -> ValidadorRevocacion.MOTIVO.equals(e.getDescription()))) {\n                return ValidadorRevocacion.MOTIVO;\n            }\n        }\n        return MOTIVO_GENERICO;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/seguridad/ListenerRevocaciones.java": "package com.mx.josesaid.develop.inventario.seguridad;\n\nimport java.time.Instant;\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.kafka.annotation.KafkaListener;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Recibe de usuarios-accesos-ms los cierres de sesión y los aplica a la copia local de revocaciones.\n * Los eventos ajenos se ignoran; un mensaje inválido se registra y se descarta.\n * Cada arranque usa un grupo de consumo nuevo y lee el topic desde el inicio: así reconstruye las\n * revocaciones vigentes. Los eventos vencidos los descarta RevocacionSesiones.\n */\n@Component\npublic class ListenerRevocaciones {\n\n    private static final Logger log = LoggerFactory.getLogger(ListenerRevocaciones.class);\n\n    private final RevocacionSesiones revocaciones;\n    private final ObjectMapper mapper;\n\n    /** Recibe la copia local de revocaciones y el lector JSON. */\n    public ListenerRevocaciones(RevocacionSesiones revocaciones, ObjectMapper mapper) {\n        this.revocaciones = revocaciones;\n        this.mapper = mapper;\n    }\n\n    /** Aplica al instante un evento de cierre de sesión recibido por Kafka. */\n    @KafkaListener(topics = \"${seguridad.revocaciones.topico:usuarios-accesos.eventos}\",\n                   groupId = \"inventario-operaciones-ms-revocaciones-#{T(java.util.UUID).randomUUID()}\",\n                   properties = \"auto.offset.reset=earliest\")\n    public void recibir(String mensaje) {\n        try {\n            Sobre sobre = mapper.readValue(mensaje, Sobre.class);\n            String tipo = sobre.tipo();\n            if (!\"sesion-cerrada\".equals(tipo) && !\"sesiones-usuario-cerradas\".equals(tipo)) {\n                return;\n            }\n            Map<String, Object> datos = sobre.datos() == null ? Map.of() : sobre.datos();\n            Instant ocurridoEn = Instant.parse(String.valueOf(datos.get(\"ocurridoEn\")));\n            if (\"sesion-cerrada\".equals(tipo)) {\n                revocaciones.revocarSesion(String.valueOf(datos.get(\"sid\")), ocurridoEn);\n            } else {\n                revocaciones.revocarUsuario(String.valueOf(datos.get(\"usuarioId\")), ocurridoEn);\n            }\n        } catch (RuntimeException e) {\n            log.warn(\"Evento de revocación descartado: {}\", e.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Sobre que publica usuarios-accesos-ms por el outbox.\n     *\n     * @param tipo componente de tipo {@code String}.\n     * @param agregadoId componente de tipo {@code String}.\n     * @param datos componente de tipo {@code Map<String, Object>}.\n     */\n    public record Sobre(String tipo, String agregadoId, Map<String, Object> datos) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/seguridad/RevocacionSesiones.java": "package com.mx.josesaid.develop.inventario.seguridad;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\nimport org.springframework.stereotype.Component;\n\n/**\n * Sesiones cerradas, recordadas en memoria solo mientras pueda haber tokens vigentes.\n * Cada servicio mantiene su copia: un reinicio la vacía, y los tokens revocados expiran igual en 15 minutos.\n */\n@Component\npublic class RevocacionSesiones {\n\n    /** Vida del access token (15 min) más un margen. Pasado ese tiempo, ningún token revocado sigue vigente. */\n    public static final Duration VIDA = Duration.ofMinutes(20);\n\n    private final Map<String, Instant> sesiones = new ConcurrentHashMap<>();\n    private final Map<String, Instant> usuarios = new ConcurrentHashMap<>();\n\n    /** Revoca una sesión (su sid) cerrada en el instante dado. */\n    public void revocarSesion(String sid, Instant ocurridoEn) {\n        if (sid == null || vencido(ocurridoEn)) {\n            return;\n        }\n        sesiones.put(sid, ocurridoEn);\n    }\n\n    /** Revoca los tokens del usuario emitidos antes del instante dado. */\n    public void revocarUsuario(String usuarioId, Instant ocurridoEn) {\n        if (usuarioId == null || vencido(ocurridoEn)) {\n            return;\n        }\n        usuarios.merge(usuarioId, ocurridoEn, (actual, nuevoValor) -> nuevoValor.isAfter(actual) ? nuevoValor : actual);\n    }\n\n    /** true si un token con ese sid, usuario y fecha de emisión ya no debe aceptarse. */\n    public boolean revocado(String sid, String usuarioId, Instant emitidoEn) {\n        limpiar();\n        if (sid != null && sesiones.containsKey(sid)) {\n            return true;\n        }\n        Instant cerradoEn = usuarioId == null ? null : usuarios.get(usuarioId);\n        return cerradoEn != null && emitidoEn != null && emitidoEn.isBefore(cerradoEn);\n    }\n\n    /** Indica si un registro de revocación ya venció y puede descartarse. */\n    private static boolean vencido(Instant ocurridoEn) {\n        return ocurridoEn == null || ocurridoEn.plus(VIDA).isBefore(Instant.now());\n    }\n\n    /** Elimina las revocaciones vencidas para no crecer sin límite. */\n    private void limpiar() {\n        Instant limite = Instant.now().minus(VIDA);\n        sesiones.values().removeIf(t -> t.isBefore(limite));\n        usuarios.values().removeIf(t -> t.isBefore(limite));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/inventario/seguridad/ValidadorRevocacion.java": "package com.mx.josesaid.develop.inventario.seguridad;\n\nimport org.springframework.security.oauth2.core.OAuth2Error;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidator;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidatorResult;\nimport org.springframework.security.oauth2.jwt.Jwt;\n\n/** Rechaza los tokens de sesiones cerradas. Se combina con la validación estándar de firma y vencimiento. */\npublic class ValidadorRevocacion implements OAuth2TokenValidator<Jwt> {\n\n    /** Motivo que se devuelve al cliente cuando la sesión fue cerrada. */\n    public static final String MOTIVO = \"La sesion fue cerrada\";\n\n    private static final OAuth2Error REVOCADO = new OAuth2Error(\"invalid_token\", MOTIVO, null);\n\n    private final RevocacionSesiones revocaciones;\n\n    /** Recibe la copia local de revocaciones. */\n    public ValidadorRevocacion(RevocacionSesiones revocaciones) {\n        this.revocaciones = revocaciones;\n    }\n\n    /** Rechaza el JWT si su sesión o su usuario fueron revocados, aunque la firma y el vencimiento sean válidos. */\n    @Override\n    public OAuth2TokenValidatorResult validate(Jwt jwt) {\n        boolean revocado = revocaciones.revocado(jwt.getClaimAsString(\"sid\"), jwt.getSubject(), jwt.getIssuedAt());\n        return revocado ? OAuth2TokenValidatorResult.failure(REVOCADO) : OAuth2TokenValidatorResult.success();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/api/InventarioControladorAutorizacionTest.java": "package com.mx.josesaid.develop.inventario.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.inventario.application.InventarioService;\nimport com.mx.josesaid.develop.inventario.config.SeguridadConfig;\nimport com.mx.josesaid.develop.inventario.infrastructure.idempotencia.Idempotencia;\nimport java.util.List;\nimport org.assertj.core.api.Assertions;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.http.MediaType;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.GrantedAuthority;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;\n\n/**\n * Matriz de autorización de InventarioControlador.\n * Un rol permitido no debe recibir 401 ni 403; un rol no permitido debe recibir 403.\n */\n@WebMvcTest(InventarioControlador.class)\n@Import({SeguridadConfig.class, InventarioControladorAutorizacionTest.Configuracion.class})\nclass InventarioControladorAutorizacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n    private static final String ARTICULO = \"{\\\"sku\\\":\\\"SKU-1\\\",\\\"nombre\\\":\\\"Tornillo\\\",\\\"unidad\\\":\\\"pza\\\",\\\"loteObligatorio\\\":false,\\\"minimo\\\":10}\";\n    private static final String ALMACEN = \"{\\\"nombre\\\":\\\"Central\\\",\\\"ubicacion\\\":\\\"Zapopan\\\"}\";\n    private static final String MOVIMIENTO = \"{\\\"articuloId\\\":\\\"\" + ID + \"\\\",\\\"almacenId\\\":\\\"\" + ID + \"\\\",\\\"tipo\\\":\\\"ENTRADA\\\",\\\"cantidad\\\":5}\";\n    private static final String ORDEN = \"{\\\"tipo\\\":\\\"PRODUCCION\\\",\\\"cantidadObjetivo\\\":10}\";\n    private static final String CIERRE = \"{\\\"cantidadReal\\\":9}\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private InventarioService servicio;\n\n    @MockitoBean\n    private Idempotencia idempotencia;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    private MockHttpServletRequestBuilder peticion(MockHttpServletRequestBuilder base, String rol) {\n        List<GrantedAuthority> autoridades = rol.isEmpty() ? List.of()\n                : List.of(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n        return base.with(jwt().jwt(j -> j.subject(SUJETO)).authorities(autoridades));\n    }\n\n    private void permitido(MockHttpServletRequestBuilder req, String descripcion, String rol) throws Exception {\n        int codigo;\n        try {\n            codigo = mvc.perform(req).andReturn().getResponse().getStatus();\n        } catch (jakarta.servlet.ServletException e) {\n            codigo = 200; // llegó al controlador: el rol fue aceptado\n        }\n        Assertions.assertThat(codigo)\n                .as(\"%s debería estar permitido para %s\", descripcion, rol)\n                .isNotIn(401, 403);\n    }\n\n    private void denegado(MockHttpServletRequestBuilder req) throws Exception {\n        mvc.perform(req).andExpect(status().isForbidden());\n    }\n\n    private static MockHttpServletRequestBuilder json(MockHttpServletRequestBuilder b, String cuerpo) {\n        return b.contentType(MediaType.APPLICATION_JSON).content(cuerpo);\n    }\n\n    @Test\n    void crearArticulo() throws Exception {\n        permitido(peticion(json(post(\"/v1/articulos\"), ARTICULO), \"OPERACIONES\"), \"POST articulos\", \"OPERACIONES\");\n        denegado(peticion(json(post(\"/v1/articulos\"), ARTICULO), \"ALMACEN\"));\n    }\n\n    @Test\n    void crearAlmacen() throws Exception {\n        permitido(peticion(json(post(\"/v1/almacenes\"), ALMACEN), \"ALMACEN\"), \"POST almacenes\", \"ALMACEN\");\n        denegado(peticion(json(post(\"/v1/almacenes\"), ALMACEN), \"OPERACIONES\"));\n    }\n\n    @Test\n    void registrarMovimiento() throws Exception {\n        permitido(peticion(json(post(\"/v1/movimientos\"), MOVIMIENTO), \"ALMACEN\"), \"POST movimientos\", \"ALMACEN\");\n        denegado(peticion(json(post(\"/v1/movimientos\"), MOVIMIENTO), \"COMPRAS\"));\n    }\n\n    @Test\n    void articulosBajoMinimo() throws Exception {\n        String ruta = \"/v1/articulos/bajo-minimo\";\n        permitido(peticion(get(ruta), \"ALMACEN\"), \"GET bajo-minimo\", \"ALMACEN\");\n        permitido(peticion(get(ruta), \"COMPRAS\"), \"GET bajo-minimo\", \"COMPRAS\");\n        denegado(peticion(get(ruta), \"VENTAS\"));\n    }\n\n    @Test\n    void movimientosDeArticulo() throws Exception {\n        String ruta = \"/v1/movimientos?articulo=\" + ID;\n        permitido(peticion(get(ruta), \"ALMACEN\"), \"GET movimientos\", \"ALMACEN\");\n        permitido(peticion(get(ruta), \"COMPRAS\"), \"GET movimientos\", \"COMPRAS\");\n        denegado(peticion(get(ruta), \"VENTAS\"));\n    }\n\n    @Test\n    void existencias() throws Exception {\n        String ruta = \"/v1/existencias?articulo=\" + ID;\n        permitido(peticion(get(ruta), \"ALMACEN\"), \"GET existencias\", \"ALMACEN\");\n        permitido(peticion(get(ruta), \"COMPRAS\"), \"GET existencias\", \"COMPRAS\");\n        permitido(peticion(get(ruta), \"VENTAS\"), \"GET existencias\", \"VENTAS\");\n        denegado(peticion(get(ruta), \"CALIDAD\"));\n    }\n\n    @Test\n    void crearOrdenOperacion() throws Exception {\n        permitido(peticion(json(post(\"/v1/ordenes-operacion\"), ORDEN), \"OPERACIONES\"), \"POST ordenes\", \"OPERACIONES\");\n        denegado(peticion(json(post(\"/v1/ordenes-operacion\"), ORDEN), \"CALIDAD\"));\n    }\n\n    @Test\n    void cerrarOrdenOperacion() throws Exception {\n        String ruta = \"/v1/ordenes-operacion/\" + ID + \"/cierre\";\n        permitido(peticion(json(post(ruta), CIERRE), \"OPERACIONES\"), \"POST cierre\", \"OPERACIONES\");\n        denegado(peticion(json(post(ruta), CIERRE), \"ALMACEN\"));\n    }\n\n    @Test\n    void trazabilidadDeLote() throws Exception {\n        String ruta = \"/v1/lotes/LOTE-1/trazabilidad\";\n        permitido(peticion(get(ruta), \"OPERACIONES\"), \"GET trazabilidad\", \"OPERACIONES\");\n        permitido(peticion(get(ruta), \"CALIDAD\"), \"GET trazabilidad\", \"CALIDAD\");\n        denegado(peticion(get(ruta), \"COMPRAS\"));\n    }\n\n    @Test\n    void sinRolNoHayAcceso() throws Exception {\n        denegado(peticion(get(\"/v1/articulos/bajo-minimo\"), \"\"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/api/InventarioIT.java": "package com.mx.josesaid.develop.inventario.api;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.jayway.jsonpath.JsonPath;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.MvcResult;\nimport org.springframework.test.web.servlet.request.RequestPostProcessor;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@SpringBootTest(properties = \"inventario.jwt.jwks-uri=http://localhost:9/.well-known/jwks.json\")\n@AutoConfigureMockMvc\n@Testcontainers\nclass InventarioIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private MockMvc mvc;\n\n    @Test\n    void flujoDeInventarioConLotesReservasYOrdenes() throws Exception {\n        mvc.perform(get(\"/v1/existencias?articulo=00000000-0000-0000-0000-000000000000\"))\n                .andExpect(status().isUnauthorized());\n\n        // COMPRAS no da de alta almacenes\n        mvc.perform(post(\"/v1/almacenes\").with(rol(\"COMPRAS\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"nombre\\\":\\\"Central\\\",\\\"ubicacion\\\":\\\"Planta 1\\\"}\"))\n                .andExpect(status().isForbidden());\n\n        String articulo = crearArticulo(\"SKU-IT-1\", true);\n        String almacen = crearAlmacen();\n\n        // Artículo con lote obligatorio sin lote: 400\n        mvc.perform(post(\"/v1/movimientos\").with(rol(\"ALMACEN\"))\n                        .contentType(\"application/json\")\n                        .content(movimiento(articulo, almacen, \"ENTRADA\", \"20\", null)))\n                .andExpect(status().isBadRequest());\n\n        // Entrada con lote: 201\n        mvc.perform(post(\"/v1/movimientos\").with(rol(\"ALMACEN\"))\n                        .contentType(\"application/json\")\n                        .content(movimiento(articulo, almacen, \"ENTRADA\", \"20\", \"LOTE-A\")))\n                .andExpect(status().isCreated());\n\n        // Salida mayor que la existencia: 409\n        mvc.perform(post(\"/v1/movimientos\").with(rol(\"ALMACEN\"))\n                        .contentType(\"application/json\")\n                        .content(movimiento(articulo, almacen, \"SALIDA\", \"25\", \"LOTE-A\")))\n                .andExpect(status().isConflict());\n\n        // Reserva y consulta de existencias\n        mvc.perform(post(\"/v1/movimientos\").with(rol(\"ALMACEN\"))\n                        .contentType(\"application/json\")\n                        .content(movimiento(articulo, almacen, \"RESERVA\", \"5\", \"LOTE-A\")))\n                .andExpect(status().isCreated());\n        mvc.perform(get(\"/v1/existencias?articulo=\" + articulo).with(rol(\"VENTAS\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$[0].disponible\").value(15));\n\n        // Trazabilidad del lote\n        mvc.perform(get(\"/v1/lotes/LOTE-A/trazabilidad\").with(rol(\"CALIDAD\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.length()\").value(2));\n\n        // Orden de producción: cierre con cantidad real\n        MvcResult orden = mvc.perform(post(\"/v1/ordenes-operacion\").with(rol(\"OPERACIONES\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"tipo\\\":\\\"PRODUCCION\\\",\\\"cantidadObjetivo\\\":50}\"))\n                .andExpect(status().isCreated())\n                .andReturn();\n        String ordenId = JsonPath.read(orden.getResponse().getContentAsString(), \"$.id\");\n        mvc.perform(post(\"/v1/ordenes-operacion/\" + ordenId + \"/cierre\").with(rol(\"OPERACIONES\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"cantidadReal\\\":48}\"))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.estatus\").value(\"CERRADA\"));\n    }\n\n    private String crearArticulo(String sku, boolean loteObligatorio) throws Exception {\n        MvcResult r = mvc.perform(post(\"/v1/articulos\").with(rol(\"OPERACIONES\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"sku\\\":\\\"\" + sku + \"\\\",\\\"nombre\\\":\\\"Resina\\\",\\\"unidad\\\":\\\"KG\\\",\"\n                                + \"\\\"loteObligatorio\\\":\" + loteObligatorio + \",\\\"minimo\\\":10}\"))\n                .andExpect(status().isCreated())\n                .andReturn();\n        return JsonPath.read(r.getResponse().getContentAsString(), \"$.id\");\n    }\n\n    private String crearAlmacen() throws Exception {\n        MvcResult r = mvc.perform(post(\"/v1/almacenes\").with(rol(\"ALMACEN\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"nombre\\\":\\\"Central\\\",\\\"ubicacion\\\":\\\"Planta 1\\\"}\"))\n                .andExpect(status().isCreated())\n                .andReturn();\n        return JsonPath.read(r.getResponse().getContentAsString(), \"$.id\");\n    }\n\n    private static String movimiento(String articulo, String almacen, String tipo, String cantidad, String lote) {\n        String loteJson = lote == null ? \"null\" : \"\\\"\" + lote + \"\\\"\";\n        return \"{\\\"articuloId\\\":\\\"\" + articulo + \"\\\",\\\"almacenId\\\":\\\"\" + almacen + \"\\\",\\\"tipo\\\":\\\"\" + tipo\n                + \"\\\",\\\"cantidad\\\":\" + cantidad + \",\\\"lote\\\":\" + loteJson + \"}\";\n    }\n\n    private static RequestPostProcessor rol(String rol) {\n        return jwt().authorities(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n    }\n\n    @Test\n    void mismaIdempotencyKeyNoDuplicaElMovimiento() throws Exception {\n        String sufijo = String.valueOf(new java.util.Random().nextInt(100000));\n        MvcResult art = mvc.perform(post(\"/v1/articulos\").with(rol(\"OPERACIONES\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"sku\\\":\\\"SKU-REPLAY-\" + sufijo + \"\\\",\\\"nombre\\\":\\\"Resina\\\",\\\"unidad\\\":\\\"KG\\\",\"\n                                + \"\\\"loteObligatorio\\\":false,\\\"minimo\\\":10}\"))\n                .andExpect(status().isCreated()).andReturn();\n        String articulo = JsonPath.read(art.getResponse().getContentAsString(), \"$.id\");\n        MvcResult alm = mvc.perform(post(\"/v1/almacenes\").with(rol(\"ALMACEN\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"nombre\\\":\\\"Replay-\" + sufijo + \"\\\",\\\"ubicacion\\\":\\\"Planta 9\\\"}\"))\n                .andExpect(status().isCreated()).andReturn();\n        String almacen = JsonPath.read(alm.getResponse().getContentAsString(), \"$.id\");\n\n        String cuerpo = movimiento(articulo, almacen, \"ENTRADA\", \"20\", null);\n        String clave = \"prueba-\" + java.util.UUID.randomUUID();\n        MvcResult primero = mvc.perform(post(\"/v1/movimientos\").with(rol(\"ALMACEN\")).header(\"Idempotency-Key\", clave)\n                        .contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isCreated()).andReturn();\n        MvcResult reintento = mvc.perform(post(\"/v1/movimientos\").with(rol(\"ALMACEN\")).header(\"Idempotency-Key\", clave)\n                        .contentType(\"application/json\").content(cuerpo))\n                .andExpect(status().isCreated()).andReturn();\n        assertEquals((String) JsonPath.read(primero.getResponse().getContentAsString(), \"$.id\"),\n                (String) JsonPath.read(reintento.getResponse().getContentAsString(), \"$.id\"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/application/InventarioBajoMinimoTest.java": "package com.mx.josesaid.develop.inventario.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.when;\n\nimport com.mx.josesaid.develop.inventario.domain.Articulo;\nimport com.mx.josesaid.develop.inventario.domain.ArticuloBajoMinimo;\nimport com.mx.josesaid.develop.inventario.domain.ArticuloRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.ExistenciaRepositorio;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass InventarioBajoMinimoTest {\n\n    @Test\n    void listaSoloLosBajoMinimoOrdenadosPorFaltante() {\n        Articulo a = Articulo.crear(\"SKU-A\", \"Tornillo\", \"pza\", false, new BigDecimal(\"10\"));\n        Articulo b = Articulo.crear(\"SKU-B\", \"Tuerca\", \"pza\", false, new BigDecimal(\"5\"));\n        Articulo c = Articulo.crear(\"SKU-C\", \"Rondana\", \"pza\", false, new BigDecimal(\"20\"));\n        ArticuloRepositorio articulos = mock(ArticuloRepositorio.class);\n        ExistenciaRepositorio existencias = mock(ExistenciaRepositorio.class);\n        when(articulos.listarConMinimo()).thenReturn(List.of(a, b, c));\n        when(existencias.cantidadTotalPorArticulo()).thenReturn(Map.of(\n                a.getId(), new BigDecimal(\"4\"),\n                b.getId(), new BigDecimal(\"8\")));\n        InventarioService servicio = new InventarioService(articulos, null, existencias, null, null,\n                mock(PublicadorEventos.class), Clock.systemUTC());\n\n        List<ArticuloBajoMinimo> resultado = servicio.listarBajoMinimo(15);\n\n        assertThat(resultado).extracting(ArticuloBajoMinimo::sku).containsExactly(\"SKU-C\", \"SKU-A\");\n        assertThat(resultado.get(0).faltante()).isEqualByComparingTo(\"20\");\n        assertThat(resultado.get(1).faltante()).isEqualByComparingTo(\"6\");\n    }\n\n    @Test\n    void respetaElLimite() {\n        Articulo a = Articulo.crear(\"SKU-A\", \"Tornillo\", \"pza\", false, new BigDecimal(\"10\"));\n        Articulo c = Articulo.crear(\"SKU-C\", \"Rondana\", \"pza\", false, new BigDecimal(\"20\"));\n        ArticuloRepositorio articulos = mock(ArticuloRepositorio.class);\n        ExistenciaRepositorio existencias = mock(ExistenciaRepositorio.class);\n        when(articulos.listarConMinimo()).thenReturn(List.of(a, c));\n        when(existencias.cantidadTotalPorArticulo()).thenReturn(Map.of());\n        InventarioService servicio = new InventarioService(articulos, null, existencias, null, null,\n                mock(PublicadorEventos.class), Clock.systemUTC());\n\n        assertThat(servicio.listarBajoMinimo(1)).extracting(ArticuloBajoMinimo::sku).containsExactly(\"SKU-C\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/application/InventarioMovimientosArticuloTest.java": "package com.mx.josesaid.develop.inventario.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\nimport static org.mockito.ArgumentMatchers.eq;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.when;\n\nimport com.mx.josesaid.develop.inventario.domain.Articulo;\nimport com.mx.josesaid.develop.inventario.domain.ArticuloRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoInventario;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.RecursoNoEncontradoException;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass InventarioMovimientosArticuloTest {\n\n    @Test\n    void devuelveLosMovimientosDelArticulo() {\n        Articulo articulo = Articulo.crear(\"SKU-A\", \"Tornillo\", \"pza\", false, new BigDecimal(\"10\"));\n        MovimientoInventario movimiento = mock(MovimientoInventario.class);\n        ArticuloRepositorio articulos = mock(ArticuloRepositorio.class);\n        MovimientoRepositorio movimientos = mock(MovimientoRepositorio.class);\n        when(articulos.buscarPorId(articulo.getId())).thenReturn(Optional.of(articulo));\n        when(movimientos.listarRecientesDeArticulo(eq(articulo.getId()), eq(15))).thenReturn(List.of(movimiento));\n        InventarioService servicio = new InventarioService(articulos, null, null, movimientos, null,\n                mock(com.mx.josesaid.develop.inventario.application.PublicadorEventos.class), Clock.systemUTC());\n\n        assertThat(servicio.movimientosDeArticulo(articulo.getId())).containsExactly(movimiento);\n    }\n\n    @Test\n    void articuloInexistenteFalla() {\n        ArticuloRepositorio articulos = mock(ArticuloRepositorio.class);\n        UUID id = UUID.randomUUID();\n        when(articulos.buscarPorId(id)).thenReturn(Optional.empty());\n        InventarioService servicio = new InventarioService(articulos, null, null, mock(MovimientoRepositorio.class),\n                null, mock(com.mx.josesaid.develop.inventario.application.PublicadorEventos.class), Clock.systemUTC());\n\n        assertThatThrownBy(() -> servicio.movimientosDeArticulo(id))\n                .isInstanceOf(RecursoNoEncontradoException.class);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/application/InventarioServiceTest.java": "package com.mx.josesaid.develop.inventario.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport com.mx.josesaid.develop.inventario.domain.*;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\n\nclass InventarioServiceTest {\n\n    private final Map<UUID, Articulo> articulos = new HashMap<>();\n    private final Map<UUID, Almacen> almacenes = new HashMap<>();\n    private final Map<String, Existencia> existencias = new HashMap<>();\n    private final List<MovimientoInventario> movs = new ArrayList<>();\n    private final List<EventoDominio> eventos = new ArrayList<>();\n    private InventarioService servicio;\n\n    @BeforeEach\n    void preparar() {\n        ArticuloRepositorio ar = new ArticuloRepositorio() {\n            public Articulo guardar(Articulo a) { articulos.put(a.getId(), a); return a; }\n            public Optional<Articulo> buscarPorId(UUID id) { return Optional.ofNullable(articulos.get(id)); }\n            public boolean existePorSku(String sku) { return articulos.values().stream().anyMatch(a -> a.getSku().equals(sku)); }\n            public Optional<Articulo> buscarPorSku(String sku) { return articulos.values().stream().filter(a -> sku.equals(a.getSku())).findFirst(); }\n            public List<Articulo> listarConMinimo() { return articulos.values().stream().filter(a -> a.getMinimo().signum() > 0).toList(); }\n        };\n        AlmacenRepositorio alr = new AlmacenRepositorio() {\n            public Almacen guardar(Almacen a) { almacenes.put(a.getId(), a); return a; }\n            public Optional<Almacen> buscarPorId(UUID id) { return Optional.ofNullable(almacenes.get(id)); }\n        };\n        ExistenciaRepositorio exr = new ExistenciaRepositorio() {\n            public Existencia guardar(Existencia e) { existencias.put(e.getArticuloId() + \"|\" + e.getAlmacenId(), e); return e; }\n            public Optional<Existencia> buscar(UUID a, UUID l) { return Optional.ofNullable(existencias.get(a + \"|\" + l)); }\n            public List<Existencia> buscarPorArticulo(UUID a) {\n                return existencias.values().stream().filter(e -> e.getArticuloId().equals(a)).toList();\n            }\n            public Map<UUID, java.math.BigDecimal> cantidadTotalPorArticulo() {\n                Map<UUID, java.math.BigDecimal> totales = new HashMap<>();\n                existencias.values().forEach(e -> totales.merge(e.getArticuloId(), e.getCantidad(), java.math.BigDecimal::add));\n                return totales;\n            }\n        };\n        MovimientoRepositorio mr = new MovimientoRepositorio() {\n            public MovimientoInventario guardar(MovimientoInventario m) { movs.add(m); return m; }\n            public List<MovimientoInventario> buscarPorLote(String lote) {\n                return movs.stream().filter(m -> lote.equals(m.getLote())).toList();\n            }\n            public List<MovimientoInventario> listarRecientesDeArticulo(UUID articuloId, int limite) {\n                return movs.stream().filter(m -> articuloId.equals(m.getArticuloId())).limit(limite).toList();\n            }\n        };\n        OrdenRepositorio or = new OrdenRepositorio() {\n            public OrdenOperacion guardar(OrdenOperacion o) { return o; }\n            public Optional<OrdenOperacion> buscarPorId(UUID id) { return Optional.empty(); }\n        };\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-10-20T10:00:00Z\"), ZoneOffset.UTC);\n        servicio = new InventarioService(ar, alr, exr, mr, or, eventos::add, reloj);\n    }\n\n    @Test\n    void articuloConLoteObligatorioExigeLote() {\n        Articulo a = servicio.crearArticulo(\"SKU-1\", \"Tornillo\", \"PZA\", true, BigDecimal.ZERO);\n        Almacen l = servicio.crearAlmacen(\"Central\", \"Planta 1\");\n        assertThatThrownBy(() -> servicio.registrarMovimiento(a.getId(), l.getId(), TipoMovimiento.ENTRADA,\n                BigDecimal.TEN, null, null)).isInstanceOf(SolicitudInvalidaException.class);\n    }\n\n    @Test\n    void salidaQueCruzaElMinimoPublicaEventoDeBajoMinimo() {\n        Articulo a = servicio.crearArticulo(\"SKU-2\", \"Resina\", \"KG\", false, new BigDecimal(\"10\"));\n        Almacen l = servicio.crearAlmacen(\"Central\", \"Planta 1\");\n        servicio.registrarMovimiento(a.getId(), l.getId(), TipoMovimiento.ENTRADA, new BigDecimal(\"15\"), null, null);\n        assertThat(eventos).isEmpty();\n        servicio.registrarMovimiento(a.getId(), l.getId(), TipoMovimiento.SALIDA, new BigDecimal(\"7\"), null, null);\n        assertThat(eventos).extracting(EventoDominio::tipo).containsExactly(InventarioService.EVENTO_BAJO_MINIMO);\n    }\n\n    @Test\n    void articuloOAlmacenInexistenteEs404() {\n        Almacen l = servicio.crearAlmacen(\"Central\", \"Planta 1\");\n        assertThatThrownBy(() -> servicio.registrarMovimiento(UUID.randomUUID(), l.getId(),\n                TipoMovimiento.ENTRADA, BigDecimal.ONE, null, null)).isInstanceOf(RecursoNoEncontradoException.class);\n    }\n\n    @Test\n    void trazabilidadSinMovimientosEs404() {\n        assertThatThrownBy(() -> servicio.trazabilidad(\"LOTE-X\")).isInstanceOf(RecursoNoEncontradoException.class);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/application/RecepcionesServiceTest.java": "package com.mx.josesaid.develop.inventario.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport com.mx.josesaid.develop.inventario.domain.Articulo;\nimport com.mx.josesaid.develop.inventario.domain.ArticuloRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.Existencia;\nimport com.mx.josesaid.develop.inventario.domain.ExistenciaRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoInventario;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.RecepcionesRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.TipoMovimiento;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.Set;\nimport java.util.UUID;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\n\nclass RecepcionesServiceTest {\n\n    private final Map<UUID, Articulo> articulos = new HashMap<>();\n    private final Map<String, Existencia> existencias = new HashMap<>();\n    private final List<MovimientoInventario> movs = new ArrayList<>();\n    private final Set<UUID> eventos = new HashSet<>();\n    private RecepcionesService servicio;\n\n    private final UUID almacen = UUID.randomUUID();\n    private final UUID orden = UUID.randomUUID();\n    private final Articulo tornillo = Articulo.crear(\"SKU-001\", \"Tornillo 3mm\", \"PZA\", false, BigDecimal.ZERO);\n    private final Articulo conLote = Articulo.crear(\"SKU-LOTE\", \"Resina\", \"KG\", true, BigDecimal.ZERO);\n\n    @BeforeEach\n    void preparar() {\n        articulos.put(tornillo.getId(), tornillo);\n        articulos.put(conLote.getId(), conLote);\n        ArticuloRepositorio ar = new ArticuloRepositorio() {\n            public Articulo guardar(Articulo a) { articulos.put(a.getId(), a); return a; }\n            public Optional<Articulo> buscarPorId(UUID id) { return Optional.ofNullable(articulos.get(id)); }\n            public boolean existePorSku(String sku) { return false; }\n            public Optional<Articulo> buscarPorSku(String sku) { return articulos.values().stream().filter(a -> sku.equals(a.getSku())).findFirst(); }\n            public List<Articulo> listarConMinimo() { return List.of(); }\n        };\n        ExistenciaRepositorio exr = new ExistenciaRepositorio() {\n            public Existencia guardar(Existencia e) { existencias.put(e.getArticuloId() + \"|\" + e.getAlmacenId(), e); return e; }\n            public Optional<Existencia> buscar(UUID a, UUID l) { return Optional.ofNullable(existencias.get(a + \"|\" + l)); }\n            public List<Existencia> buscarPorArticulo(UUID a) { return List.of(); }\n            public Map<UUID, BigDecimal> cantidadTotalPorArticulo() { return Map.of(); }\n        };\n        MovimientoRepositorio mr = new MovimientoRepositorio() {\n            public MovimientoInventario guardar(MovimientoInventario m) { movs.add(m); return m; }\n            public List<MovimientoInventario> buscarPorLote(String lote) { return List.of(); }\n            public List<MovimientoInventario> listarRecientesDeArticulo(UUID a, int limite) { return List.of(); }\n        };\n        RecepcionesRepositorio rr = eventoId -> eventos.add(eventoId);\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-11-09T21:00:00Z\"), ZoneOffset.UTC);\n        servicio = new RecepcionesService(ar, exr, mr, rr, reloj);\n    }\n\n    private void conExistencia(Articulo a, BigDecimal cantidad) {\n        existencias.put(a.getId() + \"|\" + almacen, Existencia.reconstruir(a.getId(), almacen, cantidad, BigDecimal.ZERO));\n    }\n\n    private Existencia existencia(Articulo a) {\n        return existencias.get(a.getId() + \"|\" + almacen);\n    }\n\n    @Test\n    void recepcionSumaALasExistencias() {\n        conExistencia(tornillo, new BigDecimal(\"90\"));\n\n        servicio.registrar(UUID.randomUUID(), orden, almacen,\n                List.of(new RecepcionesService.LineaRecibida(\"SKU-001\", new BigDecimal(\"20\"))));\n\n        assertThat(existencia(tornillo).getCantidad()).isEqualByComparingTo(\"110\");\n        assertThat(movs).singleElement().satisfies(m -> {\n            assertThat(m.getTipo()).isEqualTo(TipoMovimiento.ENTRADA);\n            assertThat(m.getCantidad()).isEqualByComparingTo(\"20\");\n        });\n    }\n\n    @Test\n    void mismoEventoNoSumaDosVeces() {\n        conExistencia(tornillo, new BigDecimal(\"90\"));\n        UUID evento = UUID.randomUUID();\n        var linea = new RecepcionesService.LineaRecibida(\"SKU-001\", new BigDecimal(\"20\"));\n\n        servicio.registrar(evento, orden, almacen, List.of(linea));\n        servicio.registrar(evento, orden, almacen, List.of(linea));\n\n        assertThat(existencia(tornillo).getCantidad()).isEqualByComparingTo(\"110\");\n        assertThat(movs).hasSize(1);\n    }\n\n    @Test\n    void skuDesconocidoSeOmite() {\n        conExistencia(tornillo, new BigDecimal(\"90\"));\n\n        servicio.registrar(UUID.randomUUID(), orden, almacen,\n                List.of(new RecepcionesService.LineaRecibida(\"NO-EXISTE\", new BigDecimal(\"5\"))));\n\n        assertThat(existencia(tornillo).getCantidad()).isEqualByComparingTo(\"90\");\n        assertThat(movs).isEmpty();\n    }\n\n    @Test\n    void articuloConLoteObligatorioSeOmite() {\n        conExistencia(conLote, new BigDecimal(\"10\"));\n\n        servicio.registrar(UUID.randomUUID(), orden, almacen,\n                List.of(new RecepcionesService.LineaRecibida(\"SKU-LOTE\", new BigDecimal(\"5\"))));\n\n        assertThat(existencia(conLote).getCantidad()).isEqualByComparingTo(\"10\");\n        assertThat(movs).isEmpty();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/application/ReservasPedidoServiceTest.java": "package com.mx.josesaid.develop.inventario.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport com.mx.josesaid.develop.inventario.domain.Articulo;\nimport com.mx.josesaid.develop.inventario.domain.ArticuloRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.Existencia;\nimport com.mx.josesaid.develop.inventario.domain.ExistenciaRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoInventario;\nimport com.mx.josesaid.develop.inventario.domain.MovimientoRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.ReservasPedidoRepositorio;\nimport com.mx.josesaid.develop.inventario.domain.TipoMovimiento;\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport java.util.ArrayList;\nimport java.util.HashMap;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Optional;\nimport java.util.Set;\nimport java.util.UUID;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\n\nclass ReservasPedidoServiceTest {\n\n    private final Map<UUID, Articulo> articulos = new HashMap<>();\n    private final Map<String, Existencia> existencias = new HashMap<>();\n    private final List<MovimientoInventario> movs = new ArrayList<>();\n    private final Set<String> procesados = new HashSet<>();\n    private final List<ReservasPedidoRepositorio.Reserva> reservasGuardadas = new ArrayList<>();\n    private final Map<UUID, List<ReservasPedidoRepositorio.Reserva>> reservasPorPedido = new HashMap<>();\n    private ReservasPedidoService servicio;\n\n    private final UUID almacen = UUID.randomUUID();\n    private final UUID pedido = UUID.randomUUID();\n    private final Articulo tornillo = Articulo.crear(\"SKU-001\", \"Tornillo 3mm\", \"PZA\", false, BigDecimal.ZERO);\n\n    @BeforeEach\n    void preparar() {\n        articulos.put(tornillo.getId(), tornillo);\n        ArticuloRepositorio ar = new ArticuloRepositorio() {\n            public Articulo guardar(Articulo a) { articulos.put(a.getId(), a); return a; }\n            public Optional<Articulo> buscarPorId(UUID id) { return Optional.ofNullable(articulos.get(id)); }\n            public boolean existePorSku(String sku) { return false; }\n            public Optional<Articulo> buscarPorSku(String sku) { return articulos.values().stream().filter(a -> sku.equals(a.getSku())).findFirst(); }\n            public List<Articulo> listarConMinimo() { return List.of(); }\n        };\n        ExistenciaRepositorio exr = new ExistenciaRepositorio() {\n            public Existencia guardar(Existencia e) { existencias.put(e.getArticuloId() + \"|\" + e.getAlmacenId(), e); return e; }\n            public Optional<Existencia> buscar(UUID a, UUID l) { return Optional.ofNullable(existencias.get(a + \"|\" + l)); }\n            public List<Existencia> buscarPorArticulo(UUID a) { return List.of(); }\n            public Map<UUID, BigDecimal> cantidadTotalPorArticulo() { return Map.of(); }\n        };\n        MovimientoRepositorio mr = new MovimientoRepositorio() {\n            public MovimientoInventario guardar(MovimientoInventario m) { movs.add(m); return m; }\n            public List<MovimientoInventario> buscarPorLote(String lote) { return List.of(); }\n            public List<MovimientoInventario> listarRecientesDeArticulo(UUID a, int limite) { return List.of(); }\n        };\n        ReservasPedidoRepositorio rr = new ReservasPedidoRepositorio() {\n            public boolean marcarProcesado(UUID p, String evento) { return procesados.add(p + \"|\" + evento); }\n            public void guardarReserva(UUID p, UUID a, UUID l, BigDecimal c) {\n                ReservasPedidoRepositorio.Reserva r = new ReservasPedidoRepositorio.Reserva(a, l, c);\n                reservasGuardadas.add(r);\n                reservasPorPedido.computeIfAbsent(p, k -> new ArrayList<>()).add(r);\n            }\n            public List<Reserva> reservasDe(UUID p) { return reservasPorPedido.getOrDefault(p, List.of()); }\n            public void eliminarReservas(UUID p) { reservasPorPedido.remove(p); }\n        };\n        Clock reloj = Clock.fixed(Instant.parse(\"2026-11-09T21:00:00Z\"), ZoneOffset.UTC);\n        servicio = new ReservasPedidoService(ar, exr, mr, rr, reloj);\n    }\n\n    private void conExistencia(BigDecimal cantidad, BigDecimal reservado) {\n        existencias.put(tornillo.getId() + \"|\" + almacen,\n                Existencia.reconstruir(tornillo.getId(), almacen, cantidad, reservado));\n    }\n\n    private Existencia existencia() {\n        return existencias.get(tornillo.getId() + \"|\" + almacen);\n    }\n\n    private ReservasPedidoService.LineaPedido linea(int cantidad) {\n        return new ReservasPedidoService.LineaPedido(tornillo.getId(), BigDecimal.valueOf(cantidad));\n    }\n\n    @Test\n    void alConfirmarReservaLoPedido() {\n        conExistencia(new BigDecimal(\"100\"), BigDecimal.ZERO);\n\n        servicio.reservar(pedido, almacen, List.of(linea(10)));\n\n        assertThat(existencia().getReservado()).isEqualByComparingTo(\"10\");\n        assertThat(existencia().disponible()).isEqualByComparingTo(\"90\");\n        assertThat(movs).singleElement().satisfies(m -> {\n            assertThat(m.getTipo()).isEqualTo(TipoMovimiento.RESERVA);\n            assertThat(m.getCantidad()).isEqualByComparingTo(\"10\");\n        });\n    }\n\n    @Test\n    void sinExistenciaSuficienteReservaLoQueAlcanza() {\n        conExistencia(new BigDecimal(\"5\"), BigDecimal.ZERO);\n\n        servicio.reservar(pedido, almacen, List.of(linea(10)));\n\n        assertThat(existencia().getReservado()).isEqualByComparingTo(\"5\");\n        assertThat(existencia().disponible()).isEqualByComparingTo(\"0\");\n    }\n\n    @Test\n    void sinExistenciaNoReservaNada() {\n        conExistencia(new BigDecimal(\"5\"), new BigDecimal(\"5\"));\n\n        servicio.reservar(pedido, almacen, List.of(linea(3)));\n\n        assertThat(existencia().getReservado()).isEqualByComparingTo(\"5\");\n        assertThat(movs).isEmpty();\n    }\n\n    @Test\n    void confirmarDosVecesNoDuplicaLaReserva() {\n        conExistencia(new BigDecimal(\"100\"), BigDecimal.ZERO);\n\n        servicio.reservar(pedido, almacen, List.of(linea(10)));\n        servicio.reservar(pedido, almacen, List.of(linea(10)));\n\n        assertThat(existencia().getReservado()).isEqualByComparingTo(\"10\");\n        assertThat(movs).hasSize(1);\n    }\n\n    @Test\n    void alEntregarDescuentaLoReservadoYLiberaLaReserva() {\n        conExistencia(new BigDecimal(\"100\"), BigDecimal.ZERO);\n        servicio.reservar(pedido, almacen, List.of(linea(10)));\n\n        servicio.entregar(pedido);\n\n        assertThat(existencia().getCantidad()).isEqualByComparingTo(\"90\");\n        assertThat(existencia().getReservado()).isEqualByComparingTo(\"0\");\n        assertThat(existencia().disponible()).isEqualByComparingTo(\"90\");\n        assertThat(movs).extracting(MovimientoInventario::getTipo)\n                .containsExactly(TipoMovimiento.RESERVA, TipoMovimiento.SALIDA);\n    }\n\n    @Test\n    void entregarSinReservaNoTocaExistencias() {\n        conExistencia(new BigDecimal(\"100\"), BigDecimal.ZERO);\n\n        servicio.entregar(pedido);\n\n        assertThat(existencia().getCantidad()).isEqualByComparingTo(\"100\");\n        assertThat(movs).isEmpty();\n    }\n\n    @Test\n    void entregarDosVecesNoDescuentaDosVeces() {\n        conExistencia(new BigDecimal(\"100\"), BigDecimal.ZERO);\n        servicio.reservar(pedido, almacen, List.of(linea(10)));\n        servicio.entregar(pedido);\n\n        servicio.entregar(pedido);\n\n        assertThat(existencia().getCantidad()).isEqualByComparingTo(\"90\");\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/domain/ExistenciaTest.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.math.BigDecimal;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass ExistenciaTest {\n\n    private final Existencia ex = Existencia.vacia(UUID.randomUUID(), UUID.randomUUID());\n\n    @Test\n    void entradaYSalidaActualizanLaExistencia() {\n        ex.aplicar(TipoMovimiento.ENTRADA, new BigDecimal(\"10\"));\n        ex.aplicar(TipoMovimiento.SALIDA, new BigDecimal(\"4\"));\n        assertThat(ex.getCantidad()).isEqualByComparingTo(\"6.000\");\n    }\n\n    @Test\n    void salidaMayorQueLaExistenciaSeRechazaConConflicto() {\n        ex.aplicar(TipoMovimiento.ENTRADA, new BigDecimal(\"5\"));\n        assertThatThrownBy(() -> ex.aplicar(TipoMovimiento.SALIDA, new BigDecimal(\"6\")))\n                .isInstanceOf(ConflictoException.class)\n                .hasMessageContaining(\"insuficiente\");\n    }\n\n    @Test\n    void reservaReduceLoDisponibleSinTocarLaExistencia() {\n        ex.aplicar(TipoMovimiento.ENTRADA, new BigDecimal(\"10\"));\n        ex.aplicar(TipoMovimiento.RESERVA, new BigDecimal(\"7\"));\n        assertThat(ex.disponible()).isEqualByComparingTo(\"3.000\");\n        assertThatThrownBy(() -> ex.aplicar(TipoMovimiento.SALIDA, new BigDecimal(\"4\")))\n                .isInstanceOf(ConflictoException.class);\n    }\n\n    @Test\n    void ajusteNoPuedeDejarLaExistenciaNegativaNiBajoLoReservado() {\n        ex.aplicar(TipoMovimiento.ENTRADA, new BigDecimal(\"10\"));\n        ex.aplicar(TipoMovimiento.RESERVA, new BigDecimal(\"8\"));\n        assertThatThrownBy(() -> ex.aplicar(TipoMovimiento.AJUSTE, new BigDecimal(\"-3\")))\n                .isInstanceOf(ConflictoException.class);\n        ex.aplicar(TipoMovimiento.AJUSTE, new BigDecimal(\"-2\"));\n        assertThat(ex.getCantidad()).isEqualByComparingTo(\"8.000\");\n    }\n\n    @Test\n    void cantidadesInvalidasSeRechazan() {\n        assertThatThrownBy(() -> ex.aplicar(TipoMovimiento.ENTRADA, BigDecimal.ZERO))\n                .isInstanceOf(ReglaDeNegocioException.class);\n        assertThatThrownBy(() -> ex.aplicar(TipoMovimiento.AJUSTE, BigDecimal.ZERO))\n                .isInstanceOf(ReglaDeNegocioException.class);\n        assertThatThrownBy(() -> ex.aplicar(TipoMovimiento.ENTRADA, null))\n                .isInstanceOf(ReglaDeNegocioException.class);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/domain/OrdenOperacionTest.java": "package com.mx.josesaid.develop.inventario.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.math.BigDecimal;\nimport org.junit.jupiter.api.Test;\n\nclass OrdenOperacionTest {\n\n    @Test\n    void cerrarRequiereCantidadRealMayorACero() {\n        OrdenOperacion orden = OrdenOperacion.crear(TipoOrden.PRODUCCION, new BigDecimal(\"50\"));\n        assertThatThrownBy(() -> orden.cerrar(BigDecimal.ZERO)).isInstanceOf(ReglaDeNegocioException.class);\n        orden.cerrar(new BigDecimal(\"48\"));\n        assertThat(orden.getEstatus()).isEqualTo(EstatusOrden.CERRADA);\n        assertThat(orden.getCantidadReal()).isEqualByComparingTo(\"48.000\");\n    }\n\n    @Test\n    void ordenCerradaNoSeCierraDeNuevo() {\n        OrdenOperacion orden = OrdenOperacion.crear(TipoOrden.SERVICIO, BigDecimal.ONE);\n        orden.cerrar(BigDecimal.ONE);\n        assertThatThrownBy(() -> orden.cerrar(BigDecimal.ONE)).isInstanceOf(ConflictoException.class);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/infrastructure/compras/ListenerRecepcionesTest.java": "package com.mx.josesaid.develop.inventario.infrastructure.compras;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport com.mx.josesaid.develop.inventario.application.RecepcionesService;\nimport com.mx.josesaid.develop.inventario.application.RecepcionesService.LineaRecibida;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\nimport tools.jackson.databind.ObjectMapper;\n\nclass ListenerRecepcionesTest {\n\n    private static final UUID ALMACEN = UUID.fromString(\"00000000-0000-0000-0000-0000000000a1\");\n    private static final UUID ORDEN = UUID.fromString(\"00000000-0000-0000-0000-0000000000c1\");\n    private static final UUID EVENTO = UUID.fromString(\"00000000-0000-0000-0000-0000000000e1\");\n\n    private final ServicioGrabado servicio = new ServicioGrabado();\n\n    private ListenerRecepciones conAlmacen(String almacen) {\n        return new ListenerRecepciones(servicio, new ObjectMapper(), almacen);\n    }\n\n    private static String recibido(String datos) {\n        return \"{\\\"tipo\\\":\\\"insumos-recibidos\\\",\\\"agregadoId\\\":\\\"\" + ORDEN + \"\\\",\\\"datos\\\":\" + datos + \"}\";\n    }\n\n    @Test\n    void registraLaRecepcionConSusLineas() {\n        String datos = \"{\\\"evento_id\\\":\\\"\" + EVENTO + \"\\\",\\\"lineas\\\":[{\\\"sku\\\":\\\"TOR-1\\\",\\\"cantidad\\\":\\\"5\\\"}]}\";\n\n        conAlmacen(ALMACEN.toString()).recibir(recibido(datos));\n\n        assertThat(servicio.registros).hasSize(1);\n        ServicioGrabado.Registro r = servicio.registros.get(0);\n        assertThat(r.eventoId()).isEqualTo(EVENTO);\n        assertThat(r.ordenId()).isEqualTo(ORDEN);\n        assertThat(r.almacenId()).isEqualTo(ALMACEN);\n        assertThat(r.lineas().get(0).sku()).isEqualTo(\"TOR-1\");\n    }\n\n    @Test\n    void ignoraEventosAjenos() {\n        conAlmacen(ALMACEN.toString()).recibir(\"{\\\"tipo\\\":\\\"insumos-cotizados\\\",\\\"agregadoId\\\":\\\"\" + ORDEN + \"\\\"}\");\n\n        assertThat(servicio.registros).isEmpty();\n    }\n\n    @Test\n    void descartaMensajeMalformado() {\n        conAlmacen(ALMACEN.toString()).recibir(\"{roto\");\n\n        assertThat(servicio.registros).isEmpty();\n    }\n\n    @Test\n    void descartaRecepcionSinEventoId() {\n        conAlmacen(ALMACEN.toString()).recibir(recibido(\"{\\\"lineas\\\":[{\\\"sku\\\":\\\"A\\\",\\\"cantidad\\\":\\\"1\\\"}]}\"));\n\n        assertThat(servicio.registros).isEmpty();\n    }\n\n    @Test\n    void descartaRecepcionSinDatos() {\n        conAlmacen(ALMACEN.toString()).recibir(\"{\\\"tipo\\\":\\\"insumos-recibidos\\\",\\\"agregadoId\\\":\\\"\" + ORDEN + \"\\\"}\");\n\n        assertThat(servicio.registros).isEmpty();\n    }\n\n    @Test\n    void descartaOrdenConIdentificadorInvalido() {\n        String datos = \"{\\\"evento_id\\\":\\\"\" + EVENTO + \"\\\",\\\"lineas\\\":[{\\\"sku\\\":\\\"A\\\",\\\"cantidad\\\":\\\"1\\\"}]}\";\n\n        conAlmacen(ALMACEN.toString()).recibir(\"{\\\"tipo\\\":\\\"insumos-recibidos\\\",\\\"agregadoId\\\":\\\"no-uuid\\\",\\\"datos\\\":\" + datos + \"}\");\n\n        assertThat(servicio.registros).isEmpty();\n    }\n\n    @Test\n    void descartaRecepcionSinLineas() {\n        conAlmacen(ALMACEN.toString()).recibir(recibido(\"{\\\"evento_id\\\":\\\"\" + EVENTO + \"\\\"}\"));\n        conAlmacen(ALMACEN.toString()).recibir(recibido(\"{\\\"evento_id\\\":\\\"\" + EVENTO + \"\\\",\\\"lineas\\\":\\\"no-lista\\\"}\"));\n\n        assertThat(servicio.registros).isEmpty();\n    }\n\n    @Test\n    void noRegistraSinAlmacenConfigurado() {\n        String datos = \"{\\\"evento_id\\\":\\\"\" + EVENTO + \"\\\",\\\"lineas\\\":[{\\\"sku\\\":\\\"A\\\",\\\"cantidad\\\":\\\"1\\\"}]}\";\n\n        conAlmacen(\"\").recibir(recibido(datos));\n        conAlmacen(null).recibir(recibido(datos));\n\n        assertThat(servicio.registros).isEmpty();\n    }\n\n    /** Servicio que registra las llamadas en lugar de tocar base de datos. */\n    static final class ServicioGrabado extends RecepcionesService {\n        final List<Registro> registros = new ArrayList<>();\n\n        ServicioGrabado() {\n            super(null, null, null, null, null);\n        }\n\n        @Override\n        public void registrar(UUID eventoId, UUID ordenId, UUID almacenId, List<LineaRecibida> lineas) {\n            registros.add(new Registro(eventoId, ordenId, almacenId, lineas));\n        }\n\n        record Registro(UUID eventoId, UUID ordenId, UUID almacenId, List<LineaRecibida> lineas) {\n        }\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/infrastructure/idempotencia/RegistroIdempotenciaIT.java": "package com.mx.josesaid.develop.inventario.infrastructure.idempotencia;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.junit.jupiter.api.Assertions.assertFalse;\nimport static org.junit.jupiter.api.Assertions.assertTrue;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport org.flywaydb.core.Flyway;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.jdbc.datasource.DriverManagerDataSource;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Reserva de Idempotency-Key contra PostgreSQL real (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@Testcontainers\nclass RegistroIdempotenciaIT {\n\n    @Container\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    private static final Instant T0 = Instant.parse(\"2026-11-05T12:00:00Z\");\n\n    private JdbcTemplate jdbc;\n\n    @BeforeEach\n    void migrarBaseLimpia() {\n        DriverManagerDataSource ds = new DriverManagerDataSource(\n                postgres.getJdbcUrl(), postgres.getUsername(), postgres.getPassword());\n        Flyway flyway = Flyway.configure().dataSource(ds).cleanDisabled(false).load();\n        flyway.clean();\n        flyway.migrate();\n        jdbc = new JdbcTemplate(ds);\n    }\n\n    private RegistroIdempotencia registroEn(Instant instante) {\n        return new RegistroIdempotencia(jdbc, Clock.fixed(instante, ZoneOffset.UTC));\n    }\n\n    @Test\n    void reservaFrescaNoSeRetoma() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        assertFalse(registroEn(T0.plusSeconds(60)).reservar(\"k1\", \"h1\"));\n    }\n\n    @Test\n    void reservaSinCompletarSeRetomaTrasLaConcesion() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        assertTrue(registroEn(T0.plusSeconds(180)).reservar(\"k1\", \"h2\"));\n        assertEquals(\"h2\", registroEn(T0.plusSeconds(180)).buscar(\"k1\").orElseThrow().huella());\n        assertFalse(registroEn(T0.plusSeconds(200)).reservar(\"k1\", \"h2\"));\n    }\n\n    @Test\n    void respuestaCompletadaNoSeRetomaAunquePaseLaConcesion() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        registroEn(T0).completar(\"k1\", 201, \"{}\");\n        assertFalse(registroEn(T0.plusSeconds(180)).reservar(\"k1\", \"h1\"));\n        assertTrue(registroEn(T0.plusSeconds(180)).buscar(\"k1\").orElseThrow().completada());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/infrastructure/indicadores/PublicadorIndicadoresMovimientosIT.java": "package com.mx.josesaid.develop.inventario.infrastructure.indicadores;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport com.jayway.jsonpath.JsonPath;\nimport java.time.Duration;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.Collections;\nimport java.util.Properties;\nimport java.util.UUID;\nimport org.apache.kafka.clients.consumer.ConsumerConfig;\nimport org.apache.kafka.clients.consumer.KafkaConsumer;\nimport org.apache.kafka.common.serialization.StringDeserializer;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@SpringBootTest(properties = \"inventario.jwt.jwks-uri=http://localhost:9/.well-known/jwks.json\")\n@Testcontainers\nclass PublicadorIndicadoresMovimientosIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private JdbcTemplate jdbc;\n\n    @Autowired\n    private PublicadorIndicadoresMovimientos publicador;\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    @Test\n    void movimientosDelMesCuentaTodosLosDelPeriodo() {\n        String periodo = YearMonth.now(ZONA).toString();\n        UUID articulo = UUID.randomUUID();\n        UUID almacen = UUID.randomUUID();\n        jdbc.update(\"INSERT INTO articulos (id, sku, nombre, unidad, lote_obligatorio, minimo) VALUES (?, ?, 'Tornillo', 'PZA', FALSE, 0)\",\n                articulo, \"SKU-\" + articulo.toString().substring(0, 8));\n        jdbc.update(\"INSERT INTO almacenes (id, nombre, ubicacion) VALUES (?, 'Central', 'CDMX')\", almacen);\n        movimiento(articulo, almacen, \"ENTRADA\");\n        movimiento(articulo, almacen, \"SALIDA\");\n        movimiento(articulo, almacen, \"RESERVA\");\n\n        publicador.publicarPeriodo(periodo);\n\n        String clave = PublicadorIndicadoresMovimientos.AREA + \"|\" + PublicadorIndicadoresMovimientos.NOMBRE + \"|\" + periodo;\n        String payload = leerIndicador(clave);\n        assertEquals(\"OPERACIONES\", JsonPath.read(payload, \"$.area\"));\n        assertEquals(3.0, ((Number) JsonPath.read(payload, \"$.valor\")).doubleValue(), 0.001);\n    }\n\n    private void movimiento(UUID articulo, UUID almacen, String tipo) {\n        jdbc.update(\"\"\"\n                INSERT INTO movimientos_inventario (id, articulo_id, almacen_id, tipo, cantidad, creado_utc)\n                VALUES (?, ?, ?, ?, 1.000, now())\n                \"\"\", UUID.randomUUID(), articulo, almacen, tipo);\n    }\n\n    private String leerIndicador(String clave) {\n        try (KafkaConsumer<String, String> consumidor = new KafkaConsumer<>(propiedades())) {\n            consumidor.subscribe(Collections.singletonList(\"indicadores-areas\"));\n            long limite = System.currentTimeMillis() + 30_000;\n            while (System.currentTimeMillis() < limite) {\n                for (var registro : consumidor.poll(Duration.ofMillis(500))) {\n                    if (clave.equals(registro.key())) {\n                        return registro.value();\n                    }\n                }\n            }\n            throw new AssertionError(\"No llegó el indicador \" + clave);\n        }\n    }\n\n    private Properties propiedades() {\n        Properties p = new Properties();\n        p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, kafka.getBootstrapServers());\n        p.put(ConsumerConfig.GROUP_ID_CONFIG, \"test-\" + UUID.randomUUID());\n        p.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, \"earliest\");\n        p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        return p;\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/infrastructure/pedidos/ListenerPedidosTest.java": "package com.mx.josesaid.develop.inventario.infrastructure.pedidos;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport com.mx.josesaid.develop.inventario.application.ReservasPedidoService;\nimport com.mx.josesaid.develop.inventario.application.ReservasPedidoService.LineaPedido;\nimport java.math.BigDecimal;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\nimport tools.jackson.databind.ObjectMapper;\n\nclass ListenerPedidosTest {\n\n    private static final UUID ALMACEN = UUID.fromString(\"00000000-0000-0000-0000-0000000000a1\");\n    private static final UUID PEDIDO = UUID.fromString(\"00000000-0000-0000-0000-000000000021\");\n    private static final String PRODUCTO = \"00000000-0000-0000-0000-0000000000b1\";\n\n    private final ServicioGrabado servicio = new ServicioGrabado();\n\n    private ListenerPedidos conAlmacen(String almacen) {\n        return new ListenerPedidos(servicio, new ObjectMapper(), almacen);\n    }\n\n    private static String confirmado(String datos) {\n        return \"{\\\"tipo\\\":\\\"PedidoConfirmado\\\",\\\"agregadoId\\\":\\\"\" + PEDIDO + \"\\\",\\\"datos\\\":\" + datos + \"}\";\n    }\n\n    @Test\n    void reservaLasLineasDelPedidoConfirmado() {\n        String datos = \"{\\\"lineas\\\":[{\\\"productoId\\\":\\\"\" + PRODUCTO + \"\\\",\\\"cantidad\\\":\\\"3\\\"}]}\";\n\n        conAlmacen(ALMACEN.toString()).recibir(confirmado(datos));\n\n        assertThat(servicio.reservas).hasSize(1);\n        assertThat(servicio.reservas.get(0).pedidoId()).isEqualTo(PEDIDO);\n        assertThat(servicio.reservas.get(0).almacenId()).isEqualTo(ALMACEN);\n        assertThat(servicio.reservas.get(0).lineas().get(0).cantidad()).isEqualByComparingTo(\"3\");\n    }\n\n    @Test\n    void descuentaAlEntregar() {\n        conAlmacen(ALMACEN.toString()).recibir(\n                \"{\\\"tipo\\\":\\\"PedidoEntregado\\\",\\\"agregadoId\\\":\\\"\" + PEDIDO + \"\\\",\\\"datos\\\":{}}\");\n\n        assertThat(servicio.entregados).containsExactly(PEDIDO);\n        assertThat(servicio.reservas).isEmpty();\n    }\n\n    @Test\n    void ignoraEventosAjenos() {\n        conAlmacen(ALMACEN.toString()).recibir(\"{\\\"tipo\\\":\\\"PedidoCancelado\\\",\\\"agregadoId\\\":\\\"\" + PEDIDO + \"\\\"}\");\n\n        assertThat(servicio.reservas).isEmpty();\n        assertThat(servicio.entregados).isEmpty();\n    }\n\n    @Test\n    void descartaMensajeMalformado() {\n        conAlmacen(ALMACEN.toString()).recibir(\"{roto\");\n\n        assertThat(servicio.reservas).isEmpty();\n    }\n\n    @Test\n    void descartaIdentificadorDePedidoInvalido() {\n        conAlmacen(ALMACEN.toString()).recibir(\n                \"{\\\"tipo\\\":\\\"PedidoEntregado\\\",\\\"agregadoId\\\":\\\"no-uuid\\\",\\\"datos\\\":{}}\");\n\n        assertThat(servicio.entregados).isEmpty();\n    }\n\n    @Test\n    void descartaConfirmacionSinLineas() {\n        conAlmacen(ALMACEN.toString()).recibir(confirmado(\"{\\\"sinLineas\\\":true}\"));\n        conAlmacen(ALMACEN.toString()).recibir(confirmado(\"{\\\"lineas\\\":\\\"no-lista\\\"}\"));\n        conAlmacen(ALMACEN.toString()).recibir(\"{\\\"tipo\\\":\\\"PedidoConfirmado\\\",\\\"agregadoId\\\":\\\"\" + PEDIDO + \"\\\"}\");\n\n        assertThat(servicio.reservas).isEmpty();\n    }\n\n    @Test\n    void noReservaSinAlmacenConfigurado() {\n        String datos = \"{\\\"lineas\\\":[{\\\"productoId\\\":\\\"\" + PRODUCTO + \"\\\",\\\"cantidad\\\":\\\"1\\\"}]}\";\n\n        conAlmacen(\"\").recibir(confirmado(datos));\n        conAlmacen(\"   \").recibir(confirmado(datos));\n\n        assertThat(servicio.reservas).isEmpty();\n    }\n\n    /** Servicio que registra las llamadas en lugar de tocar base de datos. */\n    static final class ServicioGrabado extends ReservasPedidoService {\n        final List<Reserva> reservas = new ArrayList<>();\n        final List<UUID> entregados = new ArrayList<>();\n\n        ServicioGrabado() {\n            super(null, null, null, null, null);\n        }\n\n        @Override\n        public void reservar(UUID pedidoId, UUID almacenId, List<LineaPedido> lineas) {\n            reservas.add(new Reserva(pedidoId, almacenId, lineas));\n        }\n\n        @Override\n        public void entregar(UUID pedidoId) {\n            entregados.add(pedidoId);\n        }\n\n        record Reserva(UUID pedidoId, UUID almacenId, List<LineaPedido> lineas) {\n        }\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/seguridad/ListenerRevocacionesTest.java": "package com.mx.josesaid.develop.inventario.seguridad;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.time.Instant;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport tools.jackson.databind.ObjectMapper;\n\nclass ListenerRevocacionesTest {\n\n    private final RevocacionSesiones revocaciones = new RevocacionSesiones();\n    private ListenerRevocaciones listener;\n\n    @BeforeEach\n    void preparar() {\n        listener = new ListenerRevocaciones(revocaciones, new ObjectMapper());\n    }\n\n    @Test\n    void aplicaCierreDeSesion() {\n        Instant ahora = Instant.now();\n        listener.recibir(\"\"\"\n                {\"tipo\":\"sesion-cerrada\",\"agregadoId\":\"u1\",\"datos\":{\"sid\":\"sid-9\",\"ocurridoEn\":\"%s\"}}\n                \"\"\".formatted(ahora));\n\n        assertThat(revocaciones.revocado(\"sid-9\", null, null)).isTrue();\n    }\n\n    @Test\n    void aplicaCierreDeTodasLasSesionesDelUsuario() {\n        Instant ahora = Instant.now();\n        listener.recibir(\"\"\"\n                {\"tipo\":\"sesiones-usuario-cerradas\",\"agregadoId\":\"u2\",\"datos\":{\"usuarioId\":\"u2\",\"ocurridoEn\":\"%s\"}}\n                \"\"\".formatted(ahora));\n\n        assertThat(revocaciones.revocado(null, \"u2\", ahora.minusSeconds(10))).isTrue();\n    }\n\n    @Test\n    void ignoraEventosAjenos() {\n        listener.recibir(\"\"\"\n                {\"tipo\":\"usuario-creado\",\"agregadoId\":\"u3\",\"datos\":{\"sid\":\"sid-x\",\"ocurridoEn\":\"%s\"}}\n                \"\"\".formatted(Instant.now()));\n\n        assertThat(revocaciones.revocado(\"sid-x\", null, null)).isFalse();\n    }\n\n    @Test\n    void descartaMensajeMalformadoSinPropagarlo() {\n        listener.recibir(\"no es json\");\n        listener.recibir(\"{\\\"tipo\\\":\\\"sesion-cerrada\\\",\\\"datos\\\":{\\\"sid\\\":\\\"s\\\",\\\"ocurridoEn\\\":\\\"no-fecha\\\"}}\");\n        listener.recibir(\"{\\\"tipo\\\":\\\"sesion-cerrada\\\",\\\"agregadoId\\\":\\\"u\\\"}\");\n\n        assertThat(revocaciones.revocado(\"s\", null, null)).isFalse();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/inventario/seguridad/RevocacionSesionesTest.java": "package com.mx.josesaid.develop.inventario.seguridad;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.time.Instant;\nimport org.junit.jupiter.api.Test;\n\nclass RevocacionSesionesTest {\n\n    private final RevocacionSesiones revocaciones = new RevocacionSesiones();\n\n    @Test\n    void revocaSesionVigenteYLaReconoce() {\n        revocaciones.revocarSesion(\"sid-1\", Instant.now());\n\n        assertThat(revocaciones.revocado(\"sid-1\", null, null)).isTrue();\n        assertThat(revocaciones.revocado(\"sid-otra\", null, null)).isFalse();\n    }\n\n    @Test\n    void ignoraSesionSinIdentificadorOSinFecha() {\n        revocaciones.revocarSesion(null, Instant.now());\n        revocaciones.revocarSesion(\"sid-2\", null);\n\n        assertThat(revocaciones.revocado(null, null, null)).isFalse();\n        assertThat(revocaciones.revocado(\"sid-2\", null, null)).isFalse();\n    }\n\n    @Test\n    void ignoraRevocacionYaVencida() {\n        Instant hace = Instant.now().minus(RevocacionSesiones.VIDA).minusSeconds(60);\n\n        revocaciones.revocarSesion(\"sid-vieja\", hace);\n        revocaciones.revocarUsuario(\"usuario-viejo\", hace);\n\n        assertThat(revocaciones.revocado(\"sid-vieja\", null, null)).isFalse();\n        assertThat(revocaciones.revocado(null, \"usuario-viejo\", Instant.now().minusSeconds(3600))).isFalse();\n    }\n\n    @Test\n    void revocaTokensDelUsuarioEmitidosAntesDelCierre() {\n        Instant cierre = Instant.now();\n        revocaciones.revocarUsuario(\"usuario-1\", cierre);\n\n        assertThat(revocaciones.revocado(null, \"usuario-1\", cierre.minusSeconds(5))).isTrue();\n        assertThat(revocaciones.revocado(null, \"usuario-1\", cierre.plusSeconds(5))).isFalse();\n    }\n\n    @Test\n    void conservaLaFechaDeCierreMasReciente() {\n        Instant reciente = Instant.now();\n        revocaciones.revocarUsuario(\"usuario-2\", reciente);\n        revocaciones.revocarUsuario(\"usuario-2\", reciente.minusSeconds(60));\n\n        assertThat(revocaciones.revocado(null, \"usuario-2\", reciente.minusSeconds(5))).isTrue();\n    }\n\n    @Test\n    void ignoraUsuarioNuloYEmitidoNulo() {\n        revocaciones.revocarUsuario(null, Instant.now());\n        revocaciones.revocarUsuario(\"usuario-3\", Instant.now());\n\n        assertThat(revocaciones.revocado(null, null, Instant.now().minusSeconds(60))).isFalse();\n        assertThat(revocaciones.revocado(null, \"usuario-3\", null)).isFalse();\n    }\n}\n"};
